const MATH_QUESTIONS = [{"id": "107d0c62", "domain": "Algebra", "skill": "Linear equations in two variables", "difficulty": "Hard", "question": "\\[0.10x + 0.20y = 0.17(x+y)\\]\nThe equation gives a volume $x$, in gallons, of a $10\\%$ solution that could be mixed with a volume $y$, in gallons, of a $20\\%$ solution to produce a $17\\%$ solution. According to this equation, what volume, in gallons, of the $20\\%$ solution could be mixed with $90.0$ gallons of the $10\\%$ solution to produce a $17\\%$ solution? (Assume that the volume of the mixture is the sum of the volumes of the two solutions before they were mixed.)", "choices": null, "table": null, "correctAnswer": ["210"], "rationale": "The correct answer is $210$. It's given that the equation $0.10x+0.20y=0.17(x+y)$ represents mixing a $10\\%$ solution and a $20\\%$ solution to obtain a $17\\%$ solution. It's also given that $x$ represents the volume, in gallons, of the $10\\%$ solution. If $90.0$ gallons of the $10\\%$ solution is used, it follows that $x=90.0$. Substituting $90.0$ for $x$ in the given equation yields $0.10(90.0)+0.20y=0.17(90.0+y)$, or $9+0.20y=15.3+0.17y$. Subtracting $0.17y$ from both sides of this equation yields $9+0.03y=15.3$. Subtracting $9$ from both sides of this equation yields $0.03y=6.3$. Dividing both sides of this equation by $0.03$ yields $y=210$. Therefore, the volume of the $20\\%$ solution that could be mixed with $90.0$ gallons of the $10\\%$ solution to produce a $17\\%$ solution is $210$ gallons."}, {"id": "55ea0659", "domain": "Algebra", "skill": "Linear equations in one variable", "difficulty": "Hard", "question": "\\[x(r-9)+4=19x+27\\]\nIn the given equation, $r$ is a positive integer. If the given equation has exactly one solution, what CANNOT be the value of $r$?", "choices": {"A": "4", "B": "9", "C": "23", "D": "28"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. In the given equation, $x(r-9)+4=19x+27$, $r$ is a positive integer. Distributing on the left-hand side of this equation yields $rx-9x+4=19x+27$. Subtracting $4$ from both sides of this equation yields $rx-9x=19x+23$. Subtracting $19x$ from both sides of this equation yields $rx-28x=23$, which can be written as $(r-28)x=23$. For this equation to have exactly one solution, the coefficient of $x$, $(r-28)$, cannot be equal to $0$. Therefore, $28$ CANNOT be the value of $r$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "088bc84e", "domain": "Algebra", "skill": "Linear equations in one variable", "difficulty": "Medium", "question": "If $2(5x)=6$, what is the value of $5x$?", "choices": {"A": "$\\dfrac{4}{5}$", "B": "$\\dfrac{5}{3}$", "C": "3", "D": "4"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Dividing both sides of the given equation by $2$ yields $5x=3$. Therefore, the value of $5x$ is $3$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "f8fa0cf0", "domain": "Algebra", "skill": "Linear equations in one variable", "difficulty": "Medium", "question": "\\[9r=7(r+7)\\]\nWhat value of $r$ is the solution to the given equation?", "choices": null, "table": null, "correctAnswer": ["24.5", "49/2"], "rationale": "The correct answer is $\\dfrac{49}{2}$. It's given that $9r=7(r+7)$. Applying the distributive property on the right-hand side of this equation yields $9r=7r+49$. Subtracting $7r$ from both sides of this equation yields $2r=49$. Dividing both sides of this equation by $2$ yields $r=\\dfrac{49}{2}$. Therefore, the solution to the given equation is $\\dfrac{49}{2}$. Note that 49/2 and 24.5 are examples of ways to enter a correct answer."}, {"id": "5eb4918d", "domain": "Algebra", "skill": "Linear equations in one variable", "difficulty": "Easy", "question": "If $9x+4=67$, what is the value of $90x+40$?", "choices": {"A": "7", "B": "70", "C": "130", "D": "670"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Multiplying both sides of the given equation by $10$ yields $10(9x+4)=10(67)$, or $90x+40=670$. Therefore, the value of $90x+40$ is $670$.\n\nChoice A is incorrect. This is the value of $x$, not $90x+40$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "935f3403", "domain": "Algebra", "skill": "Linear equations in one variable", "difficulty": "Easy", "question": "For a restaurant owner to purchase a pizza oven at a total price of $13{,}000$ dollars, a onetime down payment is required, and then fixed monthly payments are made for the remaining amount owed for the pizza oven. The equation $13{,}000=2{,}800+200t$ represents this situation, where $t$ is the number of fixed monthly payments that are made. Which of the following is the best interpretation of $200$ in this context?", "choices": {"A": "The amount, in dollars, of the down payment", "B": "The amount, in dollars, of each fixed monthly payment", "C": "The total amount, in dollars, paid for the pizza oven after $t$ fixed monthly payments", "D": "The total number of fixed monthly payments"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. It's given that the equation $13{,}000=2{,}800+200t$ represents this situation, where $t$ is the number of fixed monthly payments. In this equation, $2{,}800$ is a constant term, representing the onetime down payment, and $200$ is the coefficient of $t$. Multiplying $200$ by $t$ gives the total amount paid by the fixed monthly payments. Therefore, the best interpretation of $200$ is the amount, in dollars, of each fixed monthly payment.\n\nChoice A is incorrect. This is the best interpretation of $2{,}800$, not $200$.\n\nChoice C is incorrect. This is the best interpretation of $13{,}000$, not $200$.\n\nChoice D is incorrect. This is the best interpretation of the variable $t$, not $200$."}, {"id": "4722abd2", "domain": "Algebra", "skill": "Linear equations in two variables", "difficulty": "Medium", "question": "Line $p$ is defined by $2y+8x=11$. Line $r$ is perpendicular to line $p$ in the $xy$-plane. What is the slope of line $r$?", "choices": {"A": "$-4$", "B": "$-\\dfrac{1}{4}$", "C": "$\\dfrac{1}{4}$", "D": "4"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Line $p$: $2y+8x=11$ rewrites as $y=-4x+\\dfrac{11}{2}$, so its slope is $-4$. Perpendicular lines have slopes that are negative reciprocals, so the slope of line $r$ is $-\\dfrac{1}{(-4)}=\\dfrac{1}{4}$.\n\nChoice A is incorrect. This is the slope of line $p$, not line $r$.\n\nChoice B is incorrect. This is the reciprocal, not the negative reciprocal, of the slope of line $p$.\n\nChoice D is incorrect. This is the negative, not the negative reciprocal, of the slope of line $p$."}, {"id": "d4572f55", "domain": "Algebra", "skill": "Linear functions", "difficulty": "Hard", "question": "For a linear relationship between $x$ and $y$, the table gives three values of $x$ and their corresponding values of $y$, where $t$ is a constant. [[TABLE]]\n\nWhich equation represents this relationship?", "choices": {"A": "$y=-2x+t+23$", "B": "$y=2x+t+23$", "C": "$y=-\\dfrac{23}{17}x+t+46$", "D": "$y=\\dfrac{23}{17}x+t+46$"}, "table": {"headers": ["x", "y"], "rows": [["-34", "t"], ["-17", "t+23"], ["0", "t+46"]]}, "correctAnswer": ["D"], "rationale": "Choice D is correct. A linear equation can be written as $y=mx+b$. Using $(-34,t)$ and $(-17,t+23)$, $m=\\dfrac{(t+23)-t}{(-17)-(-34)}=\\dfrac{23}{17}$. The graph passes through $(0,t+46)$, so $b=t+46$. Thus $y=\\dfrac{23}{17}x+t+46$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "1a2a0f59", "domain": "Algebra", "skill": "Linear functions", "difficulty": "Hard", "question": "A yoga studio is offering a deal where the first session is free, the second session is half off the regular price, and the remaining sessions are at the regular price. If the regular price of a session is \\$25.40, which function $f$ gives the total cost, in dollars, of purchasing $x$ sessions using this deal, where $x \\ge 2$?", "choices": {"A": "$f(x)=25.40(x-1)+12.70$", "B": "$f(x)=25.40(x-2)+12.70$", "C": "$f(x)=25.40(x-1)+12.70(x-2)$", "D": "$f(x)=25.40(x-2)+12.70(x-1)$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. The first session is free (\\$0); the second session is half off the regular price, $25.40-(\\frac12)(25.40)=\\$12.70$; the remaining sessions are at the regular price, \\$25.40. Since two sessions have been accounted for, the remaining sessions number $x-2$. So $f(x)=0+12.70+25.40(x-2)$, or $f(x)=25.40(x-2)+12.70$.\n\nChoice A is incorrect. This function represents the total cost when the first session is half off and the remaining sessions are at the regular price.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "590d662d", "domain": "Algebra", "skill": "Linear functions", "difficulty": "Hard", "question": "While walking on a trail, Mary stopped to read a trail sign. The graph shows the total distance $y$, in meters, Mary had walked on the trail $x$ minutes after leaving the trail sign.\n\n[[FIGURE:590d662d.png]]\n\nWhat distance, in meters, did Mary walk on the trail in the $10$ minutes after leaving the trail sign?", "choices": null, "table": null, "correctAnswer": ["500"], "rationale": "The correct answer is $500$. The graph represents a linear relationship between time and distance. At $x=0$, $y=150$, and at $x=10$, $y=650$. The distance walked is the difference: $650-150=500$."}, {"id": "fc4a0d2a", "domain": "Algebra", "skill": "Linear functions", "difficulty": "Medium", "question": "\\[g(x)=3(14x-15)\\]\nWhat is the $y$-coordinate of the $y$-intercept of the graph of $y=g(x)-2$ in the $xy$-plane?", "choices": {"A": "$-47$", "B": "$-45$", "C": "$-17$", "D": "$-15$"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Substituting $3(14x-15)$ for $g(x)$ in $y=g(x)-2$ yields $y=3(14x-15)-2$. The $y$-intercept occurs when $x=0$: $y=3(14(0)-15)-2=3(-15)-2=-45-2=-47$. So the $y$-intercept is $(0,-47)$ and the $y$-coordinate is $-47$.\n\nChoice B is incorrect. This is the $y$-coordinate of the $y$-intercept of $y=g(x)$, not $y=g(x)-2$.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "2493c767", "domain": "Algebra", "skill": "Linear functions", "difficulty": "Medium", "question": "\\[s(x)=133-4x\\]\nThe function $s$ shown gives the number of spoons, $s(x)$, remaining in a dispenser $x$ minutes after the dispenser had been loaded with spoons. Which statement is the best interpretation of $s(3)=121$?", "choices": {"A": "The number of spoons remaining in the dispenser decreased by a total of $3$ spoons after $121$ minutes.", "B": "There were $3$ spoons remaining in the dispenser $121$ minutes after the dispenser had been loaded with spoons.", "C": "There were $121$ spoons remaining in the dispenser $3$ minutes after the dispenser had been loaded with spoons.", "D": "The number of spoons remaining in the dispenser decreased by a total of $121$ spoons after $3$ minutes."}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. $s(x)$ is the number of spoons remaining $x$ minutes after loading. $s(3)$ represents the value when $x=3$, so $s(3)=121$ means there were $121$ spoons remaining $3$ minutes after loading.\n\nChoice A is incorrect and may result from conceptual errors.\n\nChoice B is incorrect. This would be the best interpretation of $s(121)=3$, not $s(3)=121$.\n\nChoice D is incorrect and may result from conceptual errors."}, {"id": "0c490cd5", "domain": "Algebra", "skill": "Linear functions", "difficulty": "Easy", "question": "Sam has a flag with an area of $110$ square inches ($\\text{in}^2$). Sam plans to enlarge the flag by sewing on pieces of colored nylon, where each piece would increase the flag's area by $64\\ \\text{in}^2$. Which equation gives the flag's total area $y$, in square inches, after Sam sews on $x$ pieces of nylon?", "choices": {"A": "$y=64x$", "B": "$y=64+110x$", "C": "$y=110+64x$", "D": "$y=174x$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Each piece increases area by $64\\ \\text{in}^2$, so $x$ pieces increase area by $64x$. Adding this to the original area, $110$, gives total area $y=110+64x$.\n\nChoice A is incorrect. This equation represents the total area of $x$ pieces of colored nylon alone.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "59813abf", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Hard", "question": "\\[38(x-n)=38y+38n\\]\nOne of the equations in a system of two linear equations is given, where $n$ is a positive constant. The system has no solution. Which equation could be the second equation in this system?", "choices": {"A": "$4x-4y=8n$", "B": "$4x+4y=4n$", "C": "$4x+4y=8n$", "D": "$4x-4y=4n$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. A system of two linear equations has no solution if the lines are parallel and distinct. Distributing in the given equation yields $38x-38n=38y+38n$, so $38x-38y=76n$, i.e. $A=38,B=-38,C=76n$. For choice D, $4x-4y=4n$ has $D=4,E=-4,F=4n$. Here $D/A=4/38=2/19$, $E/B=-4/-38=2/19$ (equal slopes), and $F/C=4n/76n=1/19$ which is not equal to $2/19$ (distinct lines). So the system has no solution.\n\nChoice A is incorrect. This system has infinitely many solutions rather than no solution.\n\nChoice B is incorrect. This system has one solution rather than no solution.\n\nChoice C is incorrect. This system has one solution rather than no solution."}, {"id": "ea8bd66f", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Medium", "question": "\\[y=4x\\]\\[5x-3y=-14\\]\nThe solution to the given system of equations is $(x,y)$. What is the value of $x+y$?", "choices": {"A": "4", "B": "6", "C": "8", "D": "10"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Substituting $4x$ for $y$ in the second equation yields $5x-3(4x)=-14$, or $-7x=-14$, so $x=2$. Then $y=4(2)=8$. So $x+y=2+8=10$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This is the value of $y-x$, not $x+y$.\n\nChoice C is incorrect. This is the value of $y$, not $x+y$."}, {"id": "5e9b6079", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Hard", "question": "\\[y=7x+18\\]\nOne of the equations in a system of two linear equations is given. The system has no solution. Which equation could be the second equation in the system?", "choices": {"A": "$-21x+y=54$", "B": "$-21x+y=18$", "C": "$-7x+y=21$", "D": "$-7x+y=18$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. A system has no solution when the lines are distinct and parallel (same slope, different $y$-intercept). Choice C rewrites as $y=7x+21$, which has the same slope ($7$) as $y=7x+18$ but a different $y$-intercept ($21$ vs $18$).\n\nChoice A is incorrect. This rewrites as $y=21x+54$; the slope differs from $7$, so the lines intersect (one solution).\n\nChoice B is incorrect. This rewrites as $y=21x+18$; the slope differs from $7$, so the lines intersect (one solution).\n\nChoice D is incorrect. This rewrites as $y=7x+18$, identical to the given equation, so the system has infinitely many solutions."}, {"id": "18ac8354", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Hard", "question": "The graph of line $g$ is shown in the $xy$-plane. Line $k$ is defined by $165x+py=w$, where $p$ and $w$ are constants. If line $k$ is graphed in this $xy$-plane, resulting in the graph of a system of two linear equations, the system of two linear equations will have infinitely many solutions. What is the value of $p+w$?\n\n[[FIGURE:18ac8354.png]]", "choices": null, "table": null, "correctAnswer": ["300"], "rationale": "The correct answer is $300$. The graph of line $g$ passes through $(-10,12)$ and $(0,1)$, so its slope is $m=\\dfrac{1-12}{0-(-10)}=-\\dfrac{11}{10}$, and since it passes through $(0,1)$, $b=1$; line $g$: $y=-\\dfrac{11}{10}x+1$. Line $k$: $165x+py=w$ rewrites as $y=\\dfrac{-165}{p}x+\\dfrac{w}{p}$. For infinitely many solutions the lines must be identical, so $\\dfrac{-165}{p}=-\\dfrac{11}{10}$ and $\\dfrac{w}{p}=1$. Solving $\\dfrac{-165}{p}=-\\dfrac{11}{10}$: $1650=11p$, so $p=150$. Then $\\dfrac{w}{150}=1$ gives $w=150$. So $p+w=150+150=300$."}, {"id": "0e926898", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Easy", "question": "Students and chaperones from a middle school are going on a field trip to a museum. Admission to the museum will cost \\$8.50 for each student and \\$12 for each chaperone. It will cost a total of \\$730 for admission to the museum for all $83$ people on the field trip. How many students are going on the field trip?", "choices": {"A": "31", "B": "70", "C": "76", "D": "86"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Let $x$ = number of students and $y$ = number of chaperones. Then $x+y=83$ and $8.50x+12y=730$. From the first equation, $y=83-x$. Substituting: $8.50x+12(83-x)=730$, or $-3.50x+996=730$, so $-3.50x=-266$, giving $x=76$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "340afb12", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Medium", "question": "Ellen bought two types of snack bags for a school event. Each box of chips Ellen bought contained $24$ bags and cost \\$11. Each box of crackers Ellen bought contained $16$ bags and cost \\$9. It cost Ellen \\$497 before tax to buy $968$ bags. If $x$ is the number of boxes of chips and $y$ is the number of boxes of crackers that Ellen bought, which of the following systems of equations represents this situation?", "choices": {"A": "$11x+16y=968$\n$24x+9y=497$", "B": "$11x+9y=968$\n$24x+16y=497$", "C": "$11x+9y=497$\n$24x+16y=968$", "D": "$9x+11y=497$\n$16x+24y=968$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Each box of chips has $24$ bags, so $x$ boxes give $24x$ bags, costing $11x$ dollars. Each box of crackers has $16$ bags, so $y$ boxes give $16y$ bags, costing $9y$ dollars. Total bags: $24x+16y=968$. Total cost: $11x+9y=497$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This system represents a total cost of \\$968 and total bags of 497, the reverse of the actual situation.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "080e75c2", "domain": "Algebra", "skill": "Systems of two linear equations in two variables", "difficulty": "Medium", "question": "The functions $f$ and $g$ model the number of participants, in thousands, in two different programs $x$ years since $2010$. The graphs of $y=f(x)$ and $y=g(x)$ are shown. Which of the following could represent functions $f$ and $g$?\n\n[[FIGURE:080e75c2.png]]", "choices": {"A": "$f(x)=-\\dfrac{4}{11}x+13$\n$g(x)=\\dfrac{2}{11}x+7$", "B": "$f(x)=-\\dfrac{4}{11}x+7$\n$g(x)=\\dfrac{2}{11}x+13$", "C": "$f(x)=-\\dfrac{2}{11}x+13$\n$g(x)=\\dfrac{4}{11}x+7$", "D": "$f(x)=-\\dfrac{2}{11}x+7$\n$g(x)=\\dfrac{4}{11}x+13$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. One line passes through $(0,7)$ and $(11,11)$, giving slope $m=\\dfrac{11-7}{11-0}=\\dfrac{4}{11}$, so $y=\\dfrac{4}{11}x+7$. The other line passes through $(0,13)$ and $(11,11)$, giving slope $m=\\dfrac{11-13}{11-0}=-\\dfrac{2}{11}$, so $y=-\\dfrac{2}{11}x+13$. So $f(x)=-\\dfrac{2}{11}x+13$ and $g(x)=\\dfrac{4}{11}x+7$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "30b1e186", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "difficulty": "Medium", "question": "In the $xy$-plane, which of the following does NOT contain any points that are part of the solution set to $5x-7y>35$?", "choices": {"A": "The $x$-axis", "B": "The region where $x>0$ and $y>0$", "C": "The region where $x<0$ and $y<0$", "D": "The region where $x<0$ and $y>0$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The inequality can be written as $5x+(-7y)>35$. If $x<0$ and $y>0$, then $5x$ is negative and $-7y$ is negative, so $5x+(-7y)$ is negative and cannot be greater than $35$. Thus this region contains no points in the solution set.\n\nChoice A is incorrect. The $x$-axis contains $(10,0)$, which satisfies $5(10)-7(0)=50>35$.\n\nChoice B is incorrect. This region contains $(10,1)$, which satisfies $5(10)-7(1)=43>35$.\n\nChoice C is incorrect. This region contains $(-1,-10)$, which satisfies $5(-1)-7(-10)=65>35$."}, {"id": "d914abec", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "difficulty": "Medium", "question": "To complete a landscaping project, Adam charges a fee of \\$20.00 for his equipment and \\$9.50 per hour spent working on the project. To complete this same landscaping project, Caroline charges a fee of \\$17.00 for her equipment and \\$10.00 per hour spent working on the project. If $x$ represents the number of hours spent working on the landscaping project, what are all the values of $x$ for which Caroline's total charge is greater than Adam's total charge?", "choices": {"A": "$5\\le x\\le 6$", "B": "$6\\le x\\le 7$", "C": "$x<5$", "D": "$x>6$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Adam's total charge is $20.00+9.50x$; Caroline's is $17.00+10.00x$. Caroline's charge is greater when $17+10x>20+9.5x$, i.e. $0.5x>3$, so $x>6$.\n\nChoice A is incorrect. At $x=5$, Caroline charges $67$ and Adam charges $67.50$, so Caroline's charge is less, not greater.\n\nChoice B is incorrect. At $x=6$, both charge $77$, so they are equal, not Caroline greater.\n\nChoice C is incorrect. At $x=4$, Caroline charges $57$ and Adam charges $58$, so Caroline's charge is less."}, {"id": "e8fd6d99", "domain": "Algebra", "skill": "Linear inequalities in one or two variables", "difficulty": "Medium", "question": "Terry has a goal to collect at least $16$ items per week for a donation drive. This week, Terry has collected $4$ items. If $x$ represents the additional number of items Terry needs to collect this week to meet the goal, which inequality represents this situation?", "choices": {"A": "$4-x\\le 16$", "B": "$4+x\\le 16$", "C": "$4-x\\ge 16$", "D": "$4+x\\ge 16$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The expression $4+x$ represents the total items after collecting $x$ additional items. Since the goal is at least $16$, the inequality is $4+x\\ge 16$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This represents a goal of collecting at most, not at least, $16$ items.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "38c90632", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Hard", "question": "The expression $\\dfrac{29x+102}{x(x+51)}$ is equivalent to $\\dfrac{p}{x}+\\dfrac{w}{x+51}$, where $p$ and $w$ are constants. What is the value of $w$?", "choices": null, "table": null, "correctAnswer": ["27"], "rationale": "The correct answer is $27$. Rewriting $\\dfrac{p}{x}+\\dfrac{w}{x+51}$ with common denominator $x(x+51)$ gives $\\dfrac{p(x+51)+wx}{x(x+51)}=\\dfrac{(p+w)x+51p}{x(x+51)}$. Since this equals $\\dfrac{29x+102}{x(x+51)}$, the numerators are equal: $29x+102=(p+w)x+51p$. So $p+w=29$ and $51p=102$, giving $p=2$. Then $2+w=29$, so $w=27$."}, {"id": "00165291", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Hard", "question": "The expression $6x^4+31x^2+35$ can be rewritten as $(3x^2+a)(2x^2+b)$, where $a$ and $b$ are positive integers, or as $(3x^2+c)(2x^2+d)$, where $c$ and $d$ are positive noninteger numbers. What is the value of $a+c$?", "choices": null, "table": null, "correctAnswer": ["15.5", "31/2"], "rationale": "The correct answer is $15.5$. Expanding $(3x^2+a)(2x^2+b)=6x^4+(3b+2a)x^2+ab$. Matching with $6x^4+31x^2+35$: $3b+2a=31$ and $ab=35$. Testing positive integer factor pairs of $35$ ($1,35$; $5,7$; $7,5$; $35,1$), only $a=5,b=7$ satisfies $3(7)+2(5)=31$. So $a=5$. Similarly for $(3x^2+c)(2x^2+d)$ with $c,d$ positive noninteger: $3d+2c=31$, $cd=35$. Substituting $d=35/c$: $105+2c^2=31c$, so $2c^2-31c+105=0$, which factors as $(c-5)(2c-21)=0$, giving $c=5$ or $c=21/2=10.5$. Since $c$ is a noninteger, $c=10.5$. So $a+c=5+10.5=15.5$. Note that 15.5 and 31/2 are examples of ways to enter a correct answer."}, {"id": "04887c7b", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Medium", "question": "\\[f(x)=2x+3\\]\\[g(x)=7x-2\\]\\[h(x)=5x+6\\]\nThe functions $f$, $g$, and $h$ are defined as shown. If $f(x)\\cdot g(x)-h(x)=ax^2+bx+c$, where $a$, $b$, and $c$ are constants, what is the value of $b$?", "choices": {"A": "$-5$", "B": "12", "C": "20", "D": "22"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Substituting: $(2x+3)(7x-2)-(5x+6)=ax^2+bx+c$. Expanding: $14x^2-4x+21x-6-5x-6=ax^2+bx+c$, or $14x^2+12x-12=ax^2+bx+c$. So $b=12$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "91aa9aa9", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Easy", "question": "Which expression is equivalent to $(9x^2+6)-(8x^2)$?", "choices": {"A": "7", "B": "$17x^2+6$", "C": "$x^2-6$", "D": "$x^2+6$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The expression is equivalent to $9x^2+6-8x^2$. Combining like terms $9x^2$ and $-8x^2$ yields $x^2$. So the expression is equivalent to $x^2+6$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This is equivalent to $(9x^2+6)+(8x^2)$, not the given expression.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "f8871ccd", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Medium", "question": "Which expression is equivalent to $2\\left(x-\\dfrac{9}{2}\\right)(x+8)$?", "choices": {"A": "$2x^2-72$", "B": "$2x^2+7x-72$", "C": "$2x^2-x-36$", "D": "$x^2+7x-36$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. $2\\left(x-\\dfrac{9}{2}\\right)=2x-9$. Then $(2x-9)(x+8)=2x(x+8)-9(x+8)=2x^2+16x-9x-72=2x^2+7x-72$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "efc469c4", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Hard", "question": "\\[-14(5x-2)^2+6(5x-3)^2\\]\nThe given expression can be rewritten as $\\dfrac{a}{6}x^2+\\dfrac{b}{6}x+\\dfrac{c}{6}$, where $a$, $b$, and $c$ are constants. What is the value of $a+b+c$?", "choices": {"A": "$-612$", "B": "$-306$", "C": "$-102$", "D": "$-17$"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Expanding: $-14(25x^2-20x+4)+6(25x^2-30x+9)=(-350x^2+280x-56)+(150x^2-180x+54)=-200x^2+100x-2$. So $\\dfrac{a}{6}=-200$, $\\dfrac{b}{6}=100$, $\\dfrac{c}{6}=-2$, giving $a=-1200$, $b=600$, $c=-12$. So $a+b+c=-1200+600-12=-612$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This is the value of $\\frac{a}{6}+\\frac{b}{6}+\\frac{c}{6}$, not $a+b+c$.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "2289b199", "domain": "Advanced Math", "skill": "Equivalent expressions", "difficulty": "Hard", "question": "\\[\\dfrac{\\sqrt[3]{n^{17}p^5}}{5n^2\\left(\\sqrt[8]{p^8}\\right)}\\]\nFor all positive values of $n$ and $p$, the given expression is equivalent to which of the following?\n\nI. $\\dfrac{\\left(n^{14/3}\\right)\\left(p^{5/3}\\right)}{5np}$\n\nII. $\\dfrac{\\sqrt[3]{n^{11}p^2}}{5}$", "choices": {"A": "I only", "B": "II only", "C": "I and II", "D": "Neither I nor II"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Since $\\sqrt[N]{a}=a^{1/N}$, the expression rewrites as $\\dfrac{(n^{17}p^5)^{1/3}}{5n^2(p^8)^{1/8}}=\\dfrac{n^{17/3}p^{5/3}}{5n^2p}$. Dividing numerator and denominator by $n$ gives $\\dfrac{n^{14/3}p^{5/3}}{5np}$, which is statement I. Dividing numerator and denominator of that by $np$ gives $\\dfrac{n^{11/3}p^{2/3}}{5}=\\dfrac{\\sqrt[3]{n^{11}p^2}}{5}$, which is statement II. So the expression is equivalent to both I and II.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "46308566", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Hard", "question": "\\[r^2+qr=2r-55\\]\nIn the given equation, $q$ is an integer constant. The given equation has no real solutions. What is the largest possible value of $q$?", "choices": null, "table": null, "correctAnswer": ["16"], "rationale": "The correct answer is $16$. A quadratic $ax^2+bx+c=0$ has no real solution iff the discriminant $b^2-4ac<0$. Rewriting: $r^2+(q-2)r+55=0$, so $a=1,b=q-2,c=55$. Discriminant: $(q-2)^2-220<0$, so $(q-2)^2<220$, giving $-\\sqrt{220}<q-2<\\sqrt{220}$. Since $\\sqrt{220}\\approx14.83$, $-12.83<q<16.83$. Since $q$ is an integer, the largest possible value is $16$."}, {"id": "e833de9a", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Hard", "question": "\\[x^2+y^2=36\\]\\[y=mx+\\dfrac{b}{4}\\]\nIn the given system of equations, $m$ and $b$ are negative constants. In the $xy$-plane, the graphs of the equations in the given system intersect at the point $(-5,y)$, where $y<0$. Which expression represents the value of $b$?", "choices": {"A": "$-\\dfrac{5m}{4}+\\dfrac{\\sqrt{11}}{4}$", "B": "$\\dfrac{5m}{4}-\\dfrac{\\sqrt{11}}{4}$", "C": "$-20m+4\\sqrt{11}$", "D": "$20m-4\\sqrt{11}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Substituting $-5$ for $x$ in $x^2+y^2=36$: $25+y^2=36$, so $y^2=11$, and since $y<0$, $y=-\\sqrt{11}$. Substituting into $y=mx+\\frac{b}{4}$: $-\\sqrt{11}=m(-5)+\\frac{b}{4}$, so $-\\sqrt{11}=-5m+\\frac{b}{4}$. Adding $5m$: $5m-\\sqrt{11}=\\frac{b}{4}$. Multiplying by $4$: $b=20m-4\\sqrt{11}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "5da5c665", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Hard", "question": "\\[4x^2-5x-5=0\\]\nWhat is the greatest solution to the given equation?", "choices": {"A": "$\\dfrac{5}{8}-\\dfrac{\\sqrt{105}}{8}$", "B": "$\\dfrac{5}{8}+\\dfrac{\\sqrt{105}}{8}$", "C": "$\\dfrac{5}{4}-\\dfrac{\\sqrt{105}}{4}$", "D": "$\\dfrac{5}{4}+\\dfrac{\\sqrt{105}}{4}$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Using the quadratic formula with $a=4,b=-5,c=-5$: $x=\\dfrac{5\\pm\\sqrt{25+80}}{8}=\\dfrac{5\\pm\\sqrt{105}}{8}$. The greatest solution is $\\dfrac{5}{8}+\\dfrac{\\sqrt{105}}{8}$.\n\nChoice A is incorrect. This is the least, not the greatest, solution.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "6bd40794", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Medium", "question": "\\[(x-16)(x-10)(x+7)(x+17)=0\\]\nWhat is a positive solution to the given equation?", "choices": null, "table": null, "correctAnswer": ["10", "16"], "rationale": "The correct answer is either $10$ or $16$. By the zero product property: $x-16=0$, $x-10=0$, $x+7=0$, $x+17=0$, giving $x=16,10,-7,-17$. The positive solutions are $10$ and $16$. Note that 10 and 16 are examples of ways to enter a correct answer."}, {"id": "c8db0e19", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Hard", "question": "\\[\\dfrac{1}{4xy}+xyz=\\dfrac{1}{3yz}\\]\nIn the given equation, $x$, $y$, and $z$ are positive numbers. Which expression is equivalent to $y$?", "choices": {"A": "$\\dfrac{4x-3z}{12x^2z^2}$", "B": "$\\sqrt{\\dfrac{4x-3z}{12x^2z^2}}$", "C": "$\\dfrac{1}{3xz^2-4x^2z}$", "D": "$\\sqrt{\\dfrac{1}{3xz^2-4x^2z}}$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Multiplying both sides by $12xyz$: $12xyz\\left(\\frac{1}{4xy}+xyz\\right)=12xyz\\left(\\frac{1}{3yz}\\right)$ gives $3z+12x^2y^2z^2=4x$. Subtracting $3z$: $12x^2y^2z^2=4x-3z$. Dividing by $12x^2z^2$: $y^2=\\dfrac{4x-3z}{12x^2z^2}$. Taking the square root and using $y>0$: $y=\\sqrt{\\dfrac{4x-3z}{12x^2z^2}}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "5f10c095", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Medium", "question": "The graph of a system of a linear equation and a quadratic equation is shown. A solution to the system is $(x,y)$. What is a possible value of $x$?\n\n[[FIGURE:5f10c095.png]]", "choices": {"A": "4", "B": "5", "C": "7.2", "D": "8"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. The solutions correspond to intersection points, approximately $(4,7.2)$ and $(6,7.2)$, so possible $x$-values are $4$ and $6$. Of the choices given, only $4$ appears.\n\nChoice B is incorrect. This is the $x$-value of the vertex of the parabola, not a solution to the system.\n\nChoice C is incorrect. This is the approximate $y$-value, not $x$-value, of a solution.\n\nChoice D is incorrect. This is the $x$-value of an $x$-intercept of the parabola."}, {"id": "f123e039", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Easy", "question": "The graph of a system of a linear and a quadratic equation is shown. Which system of equations is represented by the graph?\n\n[[FIGURE:f123e039.png]]", "choices": {"A": "$y=-5x$\n$y=x^2+8$", "B": "$y=-5x$\n$y=x^2-8$", "C": "$y=5x$\n$y=x^2+8$", "D": "$y=5x$\n$y=x^2-8$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The line passes through $(0,0)$ and $(1,5)$, giving slope $m=5$, so the linear equation is $y=5x$. The parabola $y=x^2+c$ has vertex $(0,c)$; here the vertex is at $(0,-8)$, so the quadratic equation is $y=x^2-8$.\n\nChoice A is incorrect. The line has slope $-5$, not $5$, and the parabola's vertex is at $(0,8)$, not $(0,-8)$.\n\nChoice B is incorrect. The line has slope $-5$, not $5$.\n\nChoice C is incorrect. The parabola's vertex is at $(0,8)$, not $(0,-8)$."}, {"id": "9a1f1941", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Hard", "question": "\\[|4x-3|=-9\\]\nHow many solutions does the given equation have?", "choices": {"A": "Zero", "B": "One", "C": "Two", "D": "Infinitely many"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. By definition, an absolute value expression is nonnegative. Since the right-hand side, $-9$, is negative, no value of $x$ can make the equation true. The equation has zero solutions.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "30596346", "domain": "Advanced Math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "difficulty": "Hard", "question": "\\[\\dfrac{1}{7}(x-k)(16-x^2)=0\\]\nIn the given equation, $k$ is a positive constant. The sum of the solutions to the equation is $59$. What is the value of $k$?", "choices": null, "table": null, "correctAnswer": ["59"], "rationale": "The correct answer is $59$. Multiplying both sides by $7$: $(x-k)(16-x^2)=0$. By the zero product property, $x-k=0$ or $16-x^2=0$, giving $x=k$, $x=4$, $x=-4$. The sum of solutions is $k+4+(-4)=k=59$."}, {"id": "f01108a8", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "\\[y=9\\left(\\dfrac{a}{7}\\right)^{x+c}-b\\]\nHow many times does the graph of the given equation in the $xy$-plane cross the $x$-axis, where $a$, $b$, and $c$ are positive constants such that $a>7$ and $b>c$?", "choices": {"A": "Zero", "B": "One", "C": "Two", "D": "Three"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Since $a>7$, the base $\\frac{a}{7}>1$, so $9\\left(\\frac{a}{7}\\right)^{x+c}-b$ is strictly increasing in $x$. Since $b$ is positive, there is exactly one point where $y=0$, and $y$ changes sign there. So the graph crosses the $x$-axis exactly once.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "71b74a44", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Medium", "question": "\\[y=7{,}400(0.87)^x\\]\nThe given equation estimates the value, in dollars, of a certain piece of equipment $x$ years after it was purchased. According to the given equation, what was the estimated value, in dollars, of the piece of equipment at the time it was purchased?", "choices": {"A": "740", "B": "6,438", "C": "7,400", "D": "8,700"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. The value at time of purchase corresponds to $x=0$: $y=7{,}400(0.87)^0=7{,}400(1)=7{,}400$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This is the estimated value 1 year after purchase.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "3cf2698e", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Easy", "question": "The number of cells of a certain bacteria doubles every $25$ minutes during its growth period when placed in a medium of milk in a controlled laboratory environment. If a sample of $830$ cells of this bacteria is placed in milk in a controlled laboratory environment, which function $f$ best represents the number of cells of the bacteria $x$ minutes after the growth period begins, where $x$ is less than the number of minutes in the growth period?", "choices": {"A": "$f(x)=830\\left(\\dfrac12\\right)^{x/25}$", "B": "$f(x)=830(2)^{x/25}$", "C": "$f(x)=830\\left(\\dfrac13\\right)^{x/25}$", "D": "$f(x)=830(3)^{x/25}$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. For a bacteria population with initial size $P$ and doubling time $m$ minutes, the number of cells $x$ minutes after the growth period begins is $f(x)=P(2)^{x/m}$. Here $P=830$ and $m=25$, so $f(x)=830(2)^{x/25}$.\n\nChoice A is incorrect. This represents a situation where the number of cells decreases by half every 25 minutes.\n\nChoice C is incorrect. This represents a situation where the number of cells decreases by two-thirds every 25 minutes.\n\nChoice D is incorrect. This represents a situation where the number of cells triples every 25 minutes."}, {"id": "58b4c6f3", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "The function $h$ is defined by $h(x)=a^x+b$, where $a$ and $b$ are positive constants. The graph of $y=h(x)$ in the $xy$-plane passes through the points $(0,10)$ and $(2,13)$. What is the value of $ab$?", "choices": {"A": "13", "B": "18", "C": "20", "D": "26"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Substituting $(0,10)$: $10=a^0+b=1+b$, so $b=9$. Then $h(x)=a^x+9$. Substituting $(2,13)$: $13=a^2+9$, so $a^2=4$, giving $a=2$ (positive). So $ab=(2)(9)=18$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "7bbfbe70", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "A lab analyst observes a sample of a substance. An exponential model estimates that the mass, in grams, of the sample decreases by $24\\%$ every $22.96$ minutes. Which of the following equations could represent this model, where $M$ is the estimated mass, in grams, of the sample $t$ minutes after the lab analyst began observing the sample?", "choices": {"A": "$M=100(0.24)^{t+22.96}$", "B": "$M=100(0.24)^{t/22.96}$", "C": "$M=100(0.76)^{t+22.96}$", "D": "$M=100(0.76)^{t/22.96}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. A $24\\%$ decrease every $22.96$-minute interval means the mass is multiplied by $1-0.24=0.76$ each interval. Since $t/22.96$ represents the number of such intervals, the model is $M=100(0.76)^{t/22.96}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "a1e65979", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "The function $f$ is a quadratic function. In the $xy$-plane, the graph of $y=f(x)$ has a vertex at $(1,9)$ and passes through the points $(2,33)$ and $(-1,105)$. What is the value of $f(-2)-f(0)$?", "choices": {"A": "81", "B": "129", "C": "192", "D": "225"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. A quadratic with vertex $(h,k)$ has the form $y=a(x-h)^2+k$, so $f(x)=a(x-1)^2+9$. Using $(2,33)$: $33=a(1)^2+9$, so $a=24$. Thus $f(x)=24(x-1)^2+9$. $f(-2)=24(9)+9=225$. $f(0)=24(1)+9=33$. So $f(-2)-f(0)=225-33=192$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. This is the value of $f(-2)$, not $f(-2)-f(0)$."}, {"id": "5acbdc30", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "The function $f$ is defined by $f(x)=56(0.19)^x$. For any positive integer $n$, the value of $f(n)$ is $p\\%$ less than the value of $f(n-1)$. What is the value of $p$?", "choices": {"A": "19", "B": "44", "C": "56", "D": "81"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. For $f(x)=a(b)^x$ with $b<1$, $f(x)$ decreases by $100(1-b)\\%$ for every increase of $x$ by $1$. Here $b=0.19$, so the decrease is $100(1-0.19)\\%=81\\%$. Since $n$ is $1$ more than $n-1$, $f(n)$ is $81\\%$ less than $f(n-1)$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "c95686e9", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "\\[h(t)=-16t^2+b\\]\nThe function $h$ estimates a ball's height, in feet, above a floor $t$ seconds after the ball is released, where $b$ is a constant. The function estimates that the ball is $19.36$ feet above the floor when it is released at $t=0$. How many seconds after being released does the function estimate the ball will reach the floor?", "choices": null, "table": null, "correctAnswer": ["1.1", "11/10"], "rationale": "The correct answer is $1.1$. Substituting $t=0$, $h=19.36$: $19.36=-16(0)^2+b$, so $b=19.36$. Thus $h(t)=-16t^2+19.36$. Setting $h(t)=0$: $16t^2=19.36$, so $t^2=1.21$, giving $t=1.1$ (positive root). Note that 1.1 and 11/10 are examples of ways to enter a correct answer."}, {"id": "769b612d", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Medium", "question": "The function $g$ is defined by $g(x)=10^{5x-8}$. What is the value of $x$ when $g(x)$ is equal to $10{,}000$?", "choices": {"A": "$\\dfrac{11}{5}$", "B": "$\\dfrac{12}{5}$", "C": "3", "D": "4"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Since $10{,}000=10^4$, setting $10^4=10^{5x-8}$ means the exponents are equal: $4=5x-8$, so $5x=12$, giving $x=\\dfrac{12}{5}$.\n\nChoice A is incorrect. This is the value of $x$ when $g(x)=1{,}000$, not $10{,}000$.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. This is the value of $5x-8$, not $x$, when $g(x)=10{,}000$."}, {"id": "7bf77c19", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Hard", "question": "The functions $p$ and $r$ are defined by the equations shown, where $a$ and $b$ are integer constants such that $a<b$ and $b<0$. If $y=p(x)$ and $y=r(x)$ are graphed in the $xy$-plane, which of the following equations displays, as a constant or coefficient, the $y$-coordinate of the $y$-intercept of the graph of the corresponding function?\n\nI. $p(x)=a(4.1)^x+b$\n\nII. $r(x)=a(4.1)^{x+b}$", "choices": {"A": "I only", "B": "II only", "C": "I and II", "D": "Neither I nor II"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The $y$-intercept's $y$-coordinate is the value when $x=0$. For equation I: $p(0)=a(4.1)^0+b=a+b$, which is not displayed as a single constant or coefficient (it's a sum). For equation II: $r(0)=a(4.1)^{0+b}=a(4.1)^b$; since $b<0$, $(4.1)^b\\ne 1$, so $a(4.1)^b\ne a$ and (since no integers $a,b$ satisfy $a(4.1)^b=b$) it is not equal to $b$ either — the coefficient shown is $a$ and the only constant shown is $b$ in the exponent, neither of which equals $a(4.1)^b$. So neither equation displays the $y$-intercept's $y$-coordinate as a constant or coefficient.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "fe62f031", "domain": "Advanced Math", "skill": "Nonlinear functions", "difficulty": "Easy", "question": "The function $f$ is defined by $f(x)=3x^5$. In the $xy$-plane, the graph of $y=g(x)$ is the result of shifting the graph of $y=f(x)$ up $4$ units. Which equation defines the function $g$?", "choices": {"A": "$g(x)=3x^5+4$", "B": "$g(x)=3x^5-4$", "C": "$g(x)=3x^{20}$", "D": "$g(x)=12x^5$"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Shifting up $4$ units means $g(x)=f(x)+4=3x^5+4$.\n\nChoice B is incorrect. This shifts the graph down, not up, 4 units.\n\nChoice C is incorrect and may result from conceptual errors.\n\nChoice D is incorrect and may result from conceptual errors."}, {"id": "28ff3966", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "difficulty": "Hard", "question": "A square scale drawing has a side length of $55$ inches, and $1$ inch on the drawing represents an actual distance of $19$ miles. A larger version of the same drawing is printed as a square with the side length $65\\%$ longer than the side length of the previous drawing. On the larger drawing, which of the following is closest to the actual distance, in miles, represented by $1$ inch?", "choices": {"A": "6.65", "B": "11.52", "C": "31.35", "D": "35.75"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. The larger drawing's side length is $65\\%$ longer, so $1.65$ inches on the larger drawing corresponds to the same actual distance ($19$ miles) as $1$ inch on the original. So the new scale is $\\dfrac{19\\text{ miles}}{1.65\\text{ inches}}\\approx 11.52$ miles per inch.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "3e1bd4e2", "domain": "Problem-Solving and Data Analysis", "skill": "Inference from sample statistics and margin of error", "difficulty": "Medium", "question": "Researchers studied a sample of a species of fish from a certain location. The researchers found that the mean length of fish in the sample was $16.59$ millimeters. Based on the sample mean and margin of error, the researchers estimated that the mean length of all fish of this species from this location was between $15.86$ and $17.32$ millimeters. What is the margin of error, in millimeters?", "choices": {"A": "0.73", "B": "2.19", "C": "15.86", "D": "16.59"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. The margin of error is the difference between the sample mean and either bound: $16.59-15.86=0.73$ (or $17.32-16.59=0.73$).\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This is the lower bound of the estimate, not the margin of error.\n\nChoice D is incorrect. This is the sample mean, not the margin of error."}, {"id": "f6c18a66", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: Distributions and measures of center and spread", "difficulty": "Hard", "question": "For data set A, the table summarizes the distribution of the number of deliveries received by an office each day during a period of $11$ days.\n\n[[TABLE]]\n\nThe data value $13$ was recorded in error and is removed from data set A to create data set B, which consists of the remaining $10$ data values. Which statement best compares the median of data set A and the median of data set B?", "choices": {"A": "The median of data set B is less than the median of data set A.", "B": "The median of data set B is greater than the median of data set A.", "C": "The median of data set B is equal to the median of data set A.", "D": "There is not enough information to compare the medians of the two data sets."}, "table": {"headers": ["Deliveries", "Days"], "rows": [["0", "2"], ["3", "2"], ["4", "2"], ["5", "2"], ["6", "1"], ["7", "1"], ["13", "1"]]}, "correctAnswer": ["C"], "rationale": "Choice C is correct. Data set A has $11$ values, so the median is the 6th value in ascending order, which is $4$. Removing the erroneous value $13$ gives data set B with $10$ values; its median is the average of the 5th and 6th values, both $4$, so the median of B is also $4$. The medians are equal.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "d73a67d7", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: Distributions and measures of center and spread", "difficulty": "Medium", "question": "Which of the following lists represents a data set with the smallest standard deviation?", "choices": {"A": "51, 52, 54, 56, 57", "B": "52, 52, 54, 56, 56", "C": "52, 53, 54, 55, 56", "D": "53, 54, 54, 54, 55"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Standard deviation measures spread from the mean. Each list is symmetric about $54$, so $54$ is the mean of each. In choice D, all values differ from $54$ by at most $1$; in each other choice, some values differ from $54$ by more than $1$. So choice D has the smallest spread and standard deviation.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "89ff6a0a", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "difficulty": "Hard", "question": "For $100$ buttons, the table summarizes the distribution by group and diameter.\n\n[[TABLE]]\n\nOne of these buttons will be selected at random. What is the probability of selecting a button with a diameter that is less than or equal to $30$ millimeters, given that it is not in group 2? (Express your answer as a decimal or fraction, not as a percent.)", "choices": null, "table": {"headers": ["Group", "Less than 20", "20 to 30", "Greater than 30"], "rows": [["Group 1", "12", "8", "3"], ["Group 2", "0", "17", "18"], ["Group 3", "10", "32", "0"]]}, "correctAnswer": [".9538", "62/65"], "rationale": "The correct answer is $\\dfrac{62}{65}$. Buttons not in group 2 are in group 1 or group 3. Group 1 has $12+8=20$ buttons with diameter $\\le30$mm; group 3 has $10+32=42$ such buttons. Total with diameter $\\le30$mm and not in group 2: $20+42=62$. Total not in group 2: group 1 total $12+8+3=23$, group 3 total $10+32+0=42$, sum $=65$. So the probability is $\\dfrac{62}{65}$. Note that 62/65 or .9538 are examples of ways to enter a correct answer."}, {"id": "8bb94668", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "difficulty": "Hard", "question": "The speeds of objects A, B, and C are $a$ meters per second, $b$ meters per second, and $c$ meters per second, respectively. If the speed of object A is $5{,}900\\%$ of the speed of object C and the speed of object C is $0.008\\%$ of the speed of object B, which expression represents the value of $a+b$ in terms of $c$?", "choices": {"A": "1,840c", "B": "5,908c", "C": "6,025c", "D": "12,559c"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. $a=\\dfrac{5{,}900}{100}c=59c$. Also $c=\\dfrac{0.008}{100}b=0.00008b$, so $b=\\dfrac{c}{0.00008}=12{,}500c$. So $a+b=59c+12{,}500c=12{,}559c$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "dbd89c59", "domain": "Problem-Solving and Data Analysis", "skill": "Two-variable data: Models and scatterplots", "difficulty": "Easy", "question": "The scatterplot shows the relationship between the number of swans, $y$, in a certain population and the number of years since $1970$, $x$, where $0\\le x\\le 50$.\n\n[[FIGURE:dbd89c59.png]]\n\nWhich of the following equations is the most appropriate exponential model for the data shown in the scatterplot?", "choices": {"A": "$y=43(1.04)^{-x}$", "B": "$y=43(1.04)^{x}$", "C": "$y=288(1.04)^{-x}$", "D": "$y=288(1.04)^{x}$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. The data shows exponential growth (increasing as $x$ increases), so the model must have the form $y=a(b)^x$ with $a>0,b>1$ (choices B and D). The initial value $a$ should approximate the $y$-value at $x=0$, which is a little more than $40$, so $a=43$ is reasonable. Therefore $y=43(1.04)^x$ is most appropriate.\n\nChoice A is incorrect. This represents exponential decay, not growth.\n\nChoice C is incorrect. This represents exponential decay, not growth.\n\nChoice D is incorrect. This has an initial value of $288$ when $x=0$, which doesn't match the scatterplot."}, {"id": "b3547a10", "domain": "Problem-Solving and Data Analysis", "skill": "Two-variable data: Models and scatterplots", "difficulty": "Medium", "question": "A group of $10$ botanists recorded data on the germination rates of a certain type of seed for one growing season. The scatterplot shows the relationship between the number of seeds planted, $x$, and the number of seeds that germinated, $y$, for each of the botanists. A line of best fit is also shown.\n\n[[FIGURE:b3547a10.png]]\n\nWhich of the following is the best interpretation of the slope of the line of best fit in this context?", "choices": {"A": "The number of seeds planted is predicted to increase by $60$ seeds every $100$ days.", "B": "The number of seeds planted is predicted to increase by $300$ seeds every $100$ days.", "C": "The number of seeds that germinate is predicted to increase by $60$ seeds for every additional $100$ seeds that are planted.", "D": "The number of seeds that germinate is predicted to increase by $300$ seeds for every additional $100$ seeds that are planted."}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. The slope represents the change in $y$ (germinated seeds) per change in $x$ (seeds planted). The line's $y$-value increases by about $60$ when $x$ increases by about $100$, meaning about $60$ additional germinated seeds per additional $100$ seeds planted.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "4c5ea142", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportional relationships, and units", "difficulty": "Hard", "question": "On average, a certain plant grows $87$ millimeters every $m$ months. At this rate, which expression represents the number of millimeters, on average, the plant grows every $k$ years?", "choices": {"A": "$\\dfrac{29m}{4k}$", "B": "$\\dfrac{29k}{4m}$", "C": "$\\dfrac{1{,}044m}{k}$", "D": "$\\dfrac{1{,}044k}{m}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The rate is $\\dfrac{87}{m}$ millimeters per month. Since there are $12k$ months in $k$ years, the growth over $k$ years is $\\left(\\dfrac{87}{m}\\right)(12k)=\\dfrac{1{,}044k}{m}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "1b96c116", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportional relationships, and units", "difficulty": "Hard", "question": "A rectangle has an area of $3{,}168$ square inches. What is the area, in square feet, of this rectangle? ($1$ foot $=12$ inches)", "choices": {"A": "22", "B": "56.3", "C": "264", "D": "675.4"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Since $1$ foot $=12$ inches, $1$ square foot $=144$ square inches. So $3{,}168$ square inches $=3{,}168\\times\\dfrac{1\\text{ sq ft}}{144\\text{ sq in}}=22$ square feet.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This is $3{,}168/12$, not $3{,}168/144$.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "2bab1399", "domain": "Problem-Solving and Data Analysis", "skill": "Inference from sample statistics and margin of error", "difficulty": "Medium", "question": "A researcher is designing a study to investigate the average number of hours participants in a training course spend on a particular activity per day. The researcher will report an estimated average number of hours participants in the training course spend on this activity per day with an associated margin of error. The researcher is considering using a random sample of either $115$ or $230$ participants from the training course. Which of the following would be the most likely effect of using the larger random sample compared to the smaller random sample?", "choices": {"A": "The reported margin of error would be lower.", "B": "The reported margin of error would be higher.", "C": "The reported average number of hours would be lower.", "D": "The reported average number of hours would be higher."}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. A larger sample size generally leads to a smaller margin of error, so the reported margin of error would be lower.\n\nChoice B is incorrect and may result from conceptual errors.\n\nChoice C is incorrect and may result from conceptual errors.\n\nChoice D is incorrect and may result from conceptual errors."}, {"id": "f496d2c0", "domain": "Problem-Solving and Data Analysis", "skill": "Probability and conditional probability", "difficulty": "Hard", "question": "The table shows the distribution of rooms in a certain facility by seating capacity.\n\n[[TABLE]]\n\nIf a room in this facility is selected at random, which of the following is closest to the probability of selecting a room that has a seating capacity greater than $65$ seats, given that the room has a seating capacity of at least $18$ seats?", "choices": {"A": "0.24", "B": "0.32", "C": "0.50", "D": "0.92"}, "table": {"headers": ["Seating capacity", "Proportion"], "rows": [["Less than 18 seats", "26%"], ["18-40 seats", "21%"], ["41-65 seats", "29%"], ["Greater than 65 seats", "24%"]]}, "correctAnswer": ["B"], "rationale": "Choice B is correct. Rooms with at least 18 seats: $0.21+0.29+0.24=0.74$. Probability of greater than 65 seats given at least 18 seats: $\\dfrac{0.24}{0.74}\\approx0.324$, closest to $0.32$.\n\nChoice A is incorrect. This is the unconditional probability of seating capacity greater than 65, not conditioned on at least 18 seats.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "da978ee6", "domain": "Problem-Solving and Data Analysis", "skill": "Inference from sample statistics and margin of error", "difficulty": "Hard", "question": "A researcher surveyed a random sample of $1{,}020$ people from a certain city to estimate the percentage of people who support a recently announced proposal. From the survey, the researcher estimated that $86\\%$ of people from the city support this proposal, with an associated margin of error of $2.13\\%$. The researcher repeated the survey with a random sample of people from the city that was double the original sample size. Assuming the margins of error were calculated in the same way, which of the following is true about the margin of error associated with the estimate from the larger sample?", "choices": {"A": "The margin of error is between $2.13\\%$ and $3.13\\%$.", "B": "The margin of error is between $4.13\\%$ and $5.13\\%$.", "C": "The margin of error is greater than $5.13\\%$.", "D": "The margin of error is less than $2.13\\%$."}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. A larger sample size generally leads to a smaller margin of error, so the margin of error for the doubled sample is less than $2.13\\%$.\n\nChoice A is incorrect and may result from conceptual errors.\n\nChoice B is incorrect and may result from conceptual errors.\n\nChoice C is incorrect and may result from conceptual errors."}, {"id": "6feae9c3", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "difficulty": "Hard", "question": "At a recreation center, visitors used the exercise room for a total of $t$ hours in July. At the same recreation center, visitors used the exercise room for $3.49t$ hours in August. What is the percent increase in the number of hours visitors used the exercise room from July to August?", "choices": {"A": "2.49%", "B": "3.49%", "C": "249%", "D": "349%"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. The increase is $3.49t-t=2.49t$. The percent increase $p$ satisfies $\\dfrac{2.49t}{t}=\\dfrac{p}{100}$, so $p=249$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. This is the percent that August's usage is of July's usage, not the percent increase."}, {"id": "559476f4", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: Distributions and measures of center and spread", "difficulty": "Easy", "question": "The bar graph shows the frequency of each data value in a data set.\n\n[[FIGURE:559476f4.png]]\n\nWhat is the frequency of data value $2$ in this data set?", "choices": null, "table": null, "correctAnswer": ["6"], "rationale": "The correct answer is $6$. The bar corresponding to data value $2$ has a height of $6$, so its frequency is $6$."}, {"id": "70a2776f", "domain": "Problem-Solving and Data Analysis", "skill": "Two-variable data: Models and scatterplots", "difficulty": "Medium", "question": "As part of a study of lake conditions, the water temperature was recorded at different depths below the surface of a certain lake. The data shown in the scatterplot give the recorded temperature, in degrees Celsius, for $7$ depths, in meters, below the surface of the lake.\n\n[[FIGURE:70a2776f.png]]\n\nWhich of the following is closest to the slope of a line of best fit for the data shown?", "choices": {"A": "$-0.17$", "B": "$-2.17$", "C": "$-6.02$", "D": "$-8.02$"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. A line of best fit passes approximately through $(15,21.8)$ and $(70,12.7)$. Slope $=\\dfrac{12.7-21.8}{70-15}=\\dfrac{-9.1}{55}\\approx-0.165$, closest to $-0.17$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "cf2be18d", "domain": "Problem-Solving and Data Analysis", "skill": "One-variable data: Distributions and measures of center and spread", "difficulty": "Hard", "question": "\\[a,\\ 26,\\ 29,\\ b,\\ 31,\\ 47,\\ c\\]\nFor the given data set, the data values are listed in ascending order, where $a$, $b$, and $c$ are constants. For this data set, the mean is $36$, the median is $29$, and the range is $72$. What is the value of $c$?", "choices": {"A": "54", "B": "72", "C": "81", "D": "98"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. With 7 values, the median is the 4th value, so $b=29$. Mean condition: $\\dfrac{a+26+29+29+31+47+c}{7}=36$, so $a+c+162=252$, giving $a+c=90$. Range: $c-a=72$. Adding $a+c=90$ and $-a+c=72$ gives $2c=162$, so $c=81$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "de799680", "domain": "Problem-Solving and Data Analysis", "skill": "Ratios, rates, proportional relationships, and units", "difficulty": "Easy", "question": "A cluster fly is traveling at a velocity of $76$ centimeters per second. What is this velocity, in millimeters per second? ($1$ centimeter $=10$ millimeters)", "choices": {"A": "7,600", "B": "836", "C": "760", "D": "86"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. $76$ cm/s $\\times$ $10$ mm/cm $=760$ mm/s.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "98818acf", "domain": "Problem-Solving and Data Analysis", "skill": "Percentages", "difficulty": "Hard", "question": "The number of audiobooks in a library increased by $131\\%$ from last year to this year. The number of audiobooks in the library last year was $n$, and the number of audiobooks in the library this year is $bn$, where $b$ and $n$ are constants. What is the value of $b$?", "choices": null, "table": null, "correctAnswer": ["2.31"], "rationale": "The correct answer is $2.31$. Converting $131\\%$ to a decimal gives $1.31$. The number this year is $n+1.31n=2.31n$. Since this equals $bn$, $b=2.31$."}, {"id": "e89f63bf", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Medium", "question": "The sum of the measures of two angles in a triangle is $64°$. What is the measure of the third angle?", "choices": {"A": "$26°$", "B": "$52°$", "C": "$116°$", "D": "$128°$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. The angles of a triangle sum to $180°$, so the third angle is $180-64=116°$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "ecc98c87", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Medium", "question": "In the figure shown, line $k$ intersects lines $r$ and $s$. If $w=147$, which additional piece of information is sufficient to prove that lines $r$ and $s$ are parallel?\n\n[[FIGURE:ecc98c87.png]]\n(Note: Figure not drawn to scale. Line $k$ is a transversal crossing vertical lines $r$ and $s$; at the intersection with $r$, angle $w°$ is above the crossing and angle $x°$ is below it; at the intersection with $s$, angle $y°$ is above the crossing and angle $z°$ is below it. Angles $w$ and $y$ are corresponding angles, as are $x$ and $z$.)", "choices": {"A": "$x=33$", "B": "$y=147$", "C": "$w+y=180$", "D": "$y+z=180$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Angles $w°$ and $y°$ are corresponding angles. Two lines cut by a transversal are parallel iff corresponding angles are congruent. If $y=147=w$, then $w°$ and $y°$ are congruent, proving $r\\parallel s$.\n\nChoice A is incorrect. Since $x$ and $w$ form a linear pair, $x=180-147=33$ regardless of whether $r$ and $s$ are parallel.\n\nChoice C is incorrect. Substituting $w=147$ gives $y=33$; since $w$ and $y$ are corresponding angles and aren't equal, $r$ and $s$ can't be parallel.\n\nChoice D is incorrect. The relationship $y+z=180$ describes a linear pair at line $s$, true regardless of whether $r$ and $s$ are parallel."}, {"id": "1dc7e423", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Hard", "question": "In triangle $ABC$, the measure of angle $A$ is $52°$ and $AC=30$. In triangle $PQR$, the measure of angle $P$ is $52°$ and $PR=120$. Which additional piece of information is sufficient to prove that triangle $ABC$ is similar to triangle $PQR$?", "choices": {"A": "$AB=50$ and $PQ=50$.", "B": "$AB=50$ and $QR=200$.", "C": "The measures of angle $B$ and angle $R$ are $32°$ and $96°$, respectively.", "D": "The measures of angle $B$ and angle $Q$ are $52°$ and $32°$, respectively."}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Angle $A$ = angle $P$ = $52°$. If angle $B=32°$, angle $C=180-(52+32)=96°$ in triangle $ABC$. If angle $R=96°$ in triangle $PQR$, angle $Q=180-(52+96)=32°$. So angle $B$≅angle $Q$ and angle $C$≅angle $R$; with three pairs of congruent angles, the triangles are similar.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. If angle $B=52°$, angle $C=180-(52+52)=76°$. If angle $Q=32°$, which doesn't match any angle in triangle $ABC$, the triangles can't be similar."}, {"id": "b5d62bba", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Hard", "question": "In the figure, $\\overline{LQ}$ intersects $\\overline{MP}$ at point $R$, and $\\overline{LM}$ is parallel to $\\overline{PQ}$. The lengths of $\\overline{MR}$ and $\\overline{RP}$ are $8$ and $14$ units, respectively. The area of $\\triangle LMR$ is $36$ square units. What is the area of $\\triangle PQR$, in square units?\n\n[[FIGURE:b5d62bba.png]]\n(Note: Figure not drawn to scale. Points L and Q are at the far left and right on a horizontal line; M is above, P is below; segments LM and PQ are the parallel sides; R is the intersection of LQ and MP, forming a bowtie shape with triangle LMR above-left and triangle PQR below-right.)", "choices": {"A": "$\\dfrac{576}{49}$", "B": "$\\dfrac{144}{7}$", "C": "63", "D": "$\\dfrac{441}{4}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. $\\angle MRL$ and $\\angle PRQ$ are vertical angles (congruent). Since $LM\\parallel PQ$ and $LQ$ is a transversal, alternate interior angles $\\angle MLR$ and $\\angle PQR$ are congruent. So $\\triangle LMR\\sim\\triangle PQR$ (correspondence $M\\to$ well, with $MR$ corresponding to $RP$... ), and areas of similar triangles scale with the square of corresponding side lengths: $\\dfrac{\\text{area }PQR}{\\text{area }LMR}=\\left(\\dfrac{RP}{MR}\\right)^2=\\left(\\dfrac{14}{8}\\right)^2=\\left(\\dfrac74\\right)^2=\\dfrac{49}{16}$. So area of $PQR=36\\times\\dfrac{49}{16}=\\dfrac{441}{4}$.\n\nChoice A is incorrect. This results from multiplying $36$ by $(8/14)^2$ instead of $(14/8)^2$.\n\nChoice B is incorrect. This results from multiplying $36$ by $8/14$ instead of $(14/8)^2$.\n\nChoice C is incorrect. This results from multiplying $36$ by $14/8$ instead of $(14/8)^2$."}, {"id": "4a141e77", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Easy", "question": "In the figure, line $p$ is parallel to line $r$, and line $t$ intersects both lines. What is the value of $x$?\n\n[[FIGURE:4a141e77.png]]\n(Note: Figure not drawn to scale. Line $t$ crosses parallel horizontal lines $p$ (top) and $r$ (bottom). At the intersection with $p$, angle $x°$ is to the upper-left and $72°$ is to the lower-right of the crossing, i.e. $x°$ and $72°$ are vertical angles.)", "choices": {"A": "36", "B": "72", "C": "180", "D": "252"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. The angles marked $x°$ and $72°$ are vertical angles, and vertical angles are equal. So $x=72$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "7ce2e728", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Hard", "question": "For triangles $ABC$ and $FGH$, angles $B$ and $G$ each measure $51°$, the length of $\\overline{AB}$ is $6$, and the length of $\\overline{FG}$ is $18$. Which additional piece(s) of information is(are) sufficient to prove that triangle $ABC$ is similar to triangle $FGH$?\n\nI. The measure of angle $A$ is equal to the measure of angle $F$.\n\nII. The measure of angle $C$ is equal to the measure of angle $H$.\n\nIII. The length of $\\overline{FH}$ is $3$ times the length of $\\overline{AC}$.", "choices": {"A": "I is sufficient, II is sufficient, and III is sufficient.", "B": "I is sufficient and II is sufficient, but III is not.", "C": "II is sufficient and III is sufficient, but I is not.", "D": "III is sufficient, but I is not and II is not."}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. For I: if angle $A$ = angle $F$, then with angle $B$=angle $G$, two pairs of congruent angles prove similarity — sufficient. For II: if angle $C$ = angle $H$, then with angle $B$=angle $G$, two pairs of congruent angles prove similarity — sufficient. For III: $FH=3\\cdot AC$ gives ratio $3$; since $FG/AB=18/6=3$ also, there are two proportional side pairs, but angle $B$ is not the included angle between $AB$ and $AC$ (and angle $G$ not between $FG$ and $FH$), so this does not satisfy SAS similarity — not sufficient.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "7a11ceea", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Hard", "question": "In the figure, segment $AD$ and segment $BE$ intersect at point $C$. Segment $AD$ is perpendicular to line $\\ell$ at point $A$. Which of the following additional pieces of information is(are) sufficient to determine that triangle $ABC$ is congruent to triangle $DEC$?\n\nI. Segment $AD$ is perpendicular to line $m$ at point $D$.\n\nII. $AC=13$ and $DC=13$\n\n[[FIGURE:7a11ceea.png]]\n(Note: Figure not drawn to scale. Two slanted parallel-looking lines $\\ell$ and $m$ rise from lower-left to upper-right. Points on $\\ell$: B above, A below. Points on $m$: D (upper), E (lower). Segment AD crosses segment BE at point C, forming triangle ABC on the left and triangle DEC on the right, roughly a bowtie/hourglass shape.)", "choices": {"A": "I is sufficient by itself, but II is not.", "B": "II is sufficient by itself, but I is not.", "C": "I is sufficient by itself, and II is sufficient by itself.", "D": "Neither I nor II is sufficient by itself."}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Statement I (AD ⊥ m at D) makes angles BAC and EDC both right angles, so both triangles are right triangles, but at least one pair of congruent corresponding sides is still needed (for SAS or ASA) — not sufficient alone. Statement II ($AC=DC=13$) gives one pair of congruent corresponding sides, but two more congruent corresponding parts are needed (for SAS, ASA, or SSS) — not sufficient alone. Therefore neither I nor II is sufficient by itself.\n\nChoice A is incorrect and may result from conceptual errors.\n\nChoice B is incorrect and may result from conceptual errors.\n\nChoice C is incorrect and may result from conceptual errors."}, {"id": "858809e7", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Hard", "question": "In the figure, $\\overline{EG}$ and $\\overline{AD}$ intersect at point $F$, and line $\\ell$ is parallel to line $j$. If $EF=0.5CD$ and $FG=2.25CD$, which of the following must be true?\n\nI. $AB=2.25EF$\n\nII. $FG=0.5AB$\n\nIII. $\\dfrac{EF}{FG}=\\dfrac{AF}{FD}$\n\n[[FIGURE:858809e7.png]]\n(Note: Figure not drawn to scale. Line $\\ell$ (top) and line $j$ (bottom) are horizontal and parallel. Points A and B are on $\\ell$; points C and D are on $j$, with C below A and D between C and the point below B. E is on segment AC, and segments AD and EG cross at F; G is to the right, roughly on segment leading toward B, and line EG also appears to be roughly parallel to $\\ell$ and $j$. Triangle AEF and triangle ACD share vertex A; triangle DFG and triangle DAB share vertex D. Angles marked $x°$ appear at A (angle between $\\ell$ and AD), at E (angle AEF), and at D (angle FDG/ADj) — indicating these three angles are congruent.)", "choices": {"A": "I only", "B": "II only", "C": "I and II", "D": "II and III"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Since alternate interior angles marked $x°$ show $EG\\parallel \\ell \\parallel j$, triangles $AEF$ and $ACD$ are similar (AA), so with $EF=0.5CD$, $AF=0.5AD$, meaning $F$ is the midpoint of $AD$ (AD=2FD). Triangles $DFG$ and $DAB$ are also similar (AA, sharing angle $D$), so since $AD=2FD$, it follows $AB=2FG$, i.e., $FG=0.5AB$ — statement II is true. Checking statement I: $AB=2FG=2(2.25CD)=4.5CD$, while $2.25EF=2.25(0.5CD)=1.125CD$; these aren't equal, so I is false. Checking statement III: $\\frac{EF}{FG}=\\frac{0.5CD}{2.25CD}=\\frac{2}{9}$, while $\\frac{AF}{FD}=1$ (since F is the midpoint); these aren't equal, so III is false. Therefore, only statement II must be true.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "d21270da", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Easy", "question": "In the figure, line $t$ intersects lines $r$ and $s$. Which additional piece of information is sufficient to prove that lines $r$ and $s$ are parallel?\n\n[[FIGURE:d21270da.png]]\n(Note: Figure not drawn to scale. Transversal $t$ crosses horizontal line $r$ (top) with the angle below-left of the crossing marked $24°$, then crosses horizontal line $s$ (bottom) with the angle below-left of that crossing marked $x°$ — these are corresponding angles.)", "choices": {"A": "$x<24$", "B": "$x=24$", "C": "$x>24$", "D": "$x-24=360$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Two lines cut by a transversal are parallel iff a pair of corresponding (or alternate) angles are equal. The $24°$ and $x°$ angles form such a pair, so $x=24$ is sufficient to prove $r\\parallel s$.\n\nChoice A is incorrect and may result from conceptual errors.\n\nChoice C is incorrect and may result from conceptual errors.\n\nChoice D is incorrect and may result from conceptual errors."}, {"id": "697b3954", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Medium", "question": "In the figure shown, $\\triangle ABC$ is congruent to $\\triangle BDE$. If $r=54$ and $s=26$, what is the length of $\\overline{CD}$?\n\n[[FIGURE:697b3954.png]]\n(Note: Figure not drawn to scale. Points B, C, D lie on a horizontal line; A is above B with a right angle at B (side length $r=AB$); a diagonal line goes from A down to E; E is above D with a right angle at D (side $s=DE$); another diagonal connects B to E, crossing the first diagonal.)", "choices": {"A": "26", "B": "27", "C": "28", "D": "54"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Since $\\triangle ABC\\cong\\triangle BDE$ and $AB\\ne DE$, $AB$ corresponds to $BD$ and $BC$ corresponds to $DE$. So $BD=54$ and $BC=26$. Since $B,C,D$ are collinear, $BD=BC+CD$, so $54=26+CD$, giving $CD=28$.\n\nChoice A is incorrect. This is the length of $BC$, not $CD$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. This is the length of $BD$, not $CD$."}, {"id": "ffc39dc5", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Medium", "question": "In the figure shown, $CD=EF$ and $FC=DE$. If $x=65$ and $y=30$, what is the measure of $\\angle CDE$?\n\n[[FIGURE:ffc39dc5.png]]\n(Note: Figure not drawn to scale. Quadrilateral with vertices D (top-left), E (top-right), F (bottom-right), C (bottom-left); a diagonal connects D to F, splitting the quadrilateral into triangle CDF and triangle DEF. Angle $x°$ is at D between DC and DF; angle $y°$ is at F between DF and FE.)", "choices": {"A": "$30°$", "B": "$65°$", "C": "$95°$", "D": "$130°$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Since $CD=EF$ and $FC=DE$, and $DF$ is shared, $\\triangle CDF\\cong\\triangle EFD$ (SSS), with $\\angle CFD$ corresponding to $\\angle EDF$ and $\\angle CDF$ corresponding to $\\angle EFD$. Given $\\angle EDF=65°$ and $\\angle EFD=30°$ (i.e. $x=65$ is angle EDF and $y=30$ is angle EFD... following the congruence, $\\angle CFD=65°$ and $\\angle CDF=30°$). Since $\\angle CDE=\\angle CDF+\\angle FDE$, $\\angle CDE=30+65=95°$.\n\nChoice A is incorrect. This is the measure of $\\angle CDF$, not $\\angle CDE$.\n\nChoice B is incorrect. This is the measure of $\\angle CFD$, not $\\angle CDE$.\n\nChoice D is incorrect. This is the sum of $\\angle CFD$ and $\\angle EFD$, not $\\angle CDF$ and $\\angle EDF$."}, {"id": "8364487a", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Medium", "question": "Triangle $TUV$ is dilated by a scale factor of $\\dfrac12$ to obtain triangle $T'U'V'$ (not shown), where $T$ corresponds to $T'$ and $U$ corresponds to $U'$. What is the measure, in degrees, of angle $V'$?\n\n[[FIGURE:8364487a.png]]\n(Note: Figure not drawn to scale. Right triangle with right angle at U (bottom-right); V is bottom-left with angle $25°$; T is at top; VU is the horizontal base with length $76$.)", "choices": {"A": "25", "B": "38", "C": "50", "D": "76"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. A dilation preserves angle measures, so angle $V'$ = angle $V=25°$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. This is the length of $\\overline{VU}$, not the measure of angle $V'$."}, {"id": "0013adbd", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Medium", "question": "In the figure, line $t$ intersects lines $j$ and $k$. Which additional piece of information is sufficient to prove that lines $j$ and $k$ are parallel?\n\n[[FIGURE:0013adbd.png]]\n(Note: Figure not drawn to scale. Transversal $t$ crosses horizontal line $j$ (top), with angle $w°$ above-right of the crossing and $134°$ below-left; then crosses horizontal line $k$ (bottom), with angle $x°$ below-left, $y°$ below-right, and $z°$ further below (a vertical angle position) of that crossing.)", "choices": {"A": "$x=46$", "B": "$y=46$", "C": "$w=134$", "D": "$z=134$"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. The $134°$ angle and the $x°$ angle are same-side interior angles; two lines cut by a transversal are parallel if a pair of same-side interior angles sum to $180°$. If $x=46$, then $134+46=180$, proving $j\\parallel k$.\n\nChoice B is incorrect. The $y°$ and $134°$ angles are alternate interior angles; if $y=46\\ne 134$, the lines would NOT be parallel.\n\nChoice C is incorrect. The $w°$ and $134°$ angles are vertical angles, so $w=134$ regardless of whether $j$ and $k$ are parallel.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "1dacfb94", "domain": "Geometry and Trigonometry", "skill": "Lines, angles, and triangles", "difficulty": "Hard", "question": "In triangle $ABC$, $AB=BC$. Points $D$ and $E$ lie on line segments $AB$ and $BC$, respectively, such that line segments $DE$ and $AC$ are parallel. Point $O$ is the midpoint of line segment $DE$, and the measure of $\\angle OAC$ is $30°$. Point $F$ lies on line segment $AC$, and line segment $BF$ passes through point $O$. If $AB=81$ and $AO=BO$, what is the length of line segment $BE$?\n\n[[FIGURE:1dacfb94.png]]\n(Note: Figure not drawn to scale. Isosceles triangle ABC with B at top apex, A bottom-left, C bottom-right. D is on AB, E is on BC, with segment DE horizontal (parallel to AC), intersecting the vertical segment BF at point O — O is the midpoint of DE. F is on AC directly below O. A diagonal from A to O is drawn, with angle $30°$ marked at A between AO and AC/AF.)", "choices": null, "table": null, "correctAnswer": ["54"], "rationale": "The correct answer is $54$. Since $AB=BC$, triangle $ABC$ is isosceles. Since $DE\\parallel AC$, $\\triangle BDE\\sim\\triangle BAC$, so $\\triangle BDE$ is also isosceles, and since $O$ is the midpoint of $DE$, $BO$ splits $\\triangle BDE$ into two congruent triangles, making $\\angle BOD$ (and thus $\\angle BFA$) a right angle. Since $\\angle OAF=30°$, triangle $AOF$ is a 30-60-90 triangle, where the side opposite $30°$ ($OF$) is half the side opposite $90°$ ($AO$). Let $OF=x$ and $AO=2x$. Since $AO=BO$, $BO=2x$ also, so $BF=BO+OF=2x+x=3x$. Since $\\triangle BDE\\sim\\triangle BAC$, $\\dfrac{BE}{BC}=\\dfrac{BO}{BF}=\\dfrac{2x}{3x}=\\dfrac23$. Since $AB=BC=81$, $\\dfrac{BE}{81}=\\dfrac23$, giving $BE=54$."}, {"id": "2c3aefc9", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "In rectangle $PQRS$, the length of line segment $QS$ is $\\sqrt{2{,}344}$ and the length of side $PS$ is $8$ more than the length of side $RS$. What is the length of side $QR$?\n\n[[FIGURE:2c3aefc9.png]]\n(Note: Figure not drawn to scale. Rectangle with Q top-left, R top-right, P bottom-left, S bottom-right; diagonal drawn from Q to S.)", "choices": null, "table": null, "correctAnswer": ["38"], "rationale": "The correct answer is $38$. Since $QR$ is opposite $PS$ in the rectangle, $QR=PS=RS+8$. Let $x=RS$; then $QR=x+8$. Since angle $R$ is a right angle, $QR$, $RS$, and diagonal $QS$ form a right triangle with hypotenuse $QS=\\sqrt{2{,}344}$. So $x^2+(x+8)^2=2{,}344$. Expanding: $2x^2+16x+64=2{,}344$, so $x^2+8x+32=1{,}172$, i.e. $x^2+8x+16=1{,}156$, or $(x+4)^2=1{,}156$. Taking the positive square root: $x+4=34$, so $x=30$. Thus $QR=x+8=38$."}, {"id": "2757549e", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Medium", "question": "In the figure, $\\overline{BC}$ is parallel to $\\overline{DE}$. If the length of $\\overline{DE}$ is $147$ and the length of $\\overline{AE}$ is $245$, what is the value of $\\tan x°$?\n\n[[FIGURE:2757549e.png]]\n(Note: Figure not drawn to scale. Right triangle ADE with the right angle at D (bottom-left), E at bottom-right, A at top. B is on segment AD, C is on segment AE, with BC horizontal and parallel to DE; angle $x°$ is marked at C between CB and CA/CE.)", "choices": {"A": "$\\dfrac{147}{196}$", "B": "$\\dfrac{147}{245}$", "C": "$\\dfrac{196}{147}$", "D": "$\\dfrac{245}{147}$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Triangle $ADE$ is a right triangle with hypotenuse $AE=245$ and legs $AD$, $DE=147$. By the Pythagorean theorem: $AD^2+147^2=245^2$, so $AD^2=245^2-147^2=60{,}025-21{,}609=38{,}416$, giving $AD=196$. Since $BC\\parallel DE$, triangle $ABC\\sim$ triangle $ADE$, and angle $ACB$ corresponds to angle $AED$. So $\\tan x°=\\dfrac{AB}{BC}=\\dfrac{AD}{DE}=\\dfrac{196}{147}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This is the value of $\\cos x°$, not $\\tan x°$.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "c4a9c94d", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "In the figure, $\\overline{AD}$ and $\\overline{BC}$ intersect at point $D$. If the length of $\\overline{BD}$ is $5$ and the tangent of angle $CAD$ is $1.3$, what is the length of $\\overline{AD}$?\n\n[[FIGURE:c4a9c94d.png]]\n(Note: Figure not drawn to scale. Triangle BAC with right angle at A (bottom-left) and C at bottom-right; B is at top; D is on segment BC near the top, with segment AD drawn from A to D, forming a right angle at D. This creates two smaller right triangles, BDA and ADC, within the larger right triangle BAC.)", "choices": null, "table": null, "correctAnswer": ["6.5", "13/2"], "rationale": "The correct answer is $6.5$. Since $AD\\perp BC$, triangles $BDA$, $ADC$, and $BAC$ are all similar right triangles (each pair sharing an angle with the original). Since $\\triangle ADC$ and $\\triangle BDA$ are similar, angle $CAD$ in $\\triangle ADC$ corresponds to angle $ABD$ in $\\triangle BDA$, so $\\tan(ABD)=\\tan(CAD)=1.3$. In right triangle $BDA$, $\\tan(ABD)=\\dfrac{AD}{BD}$. Substituting $BD=5$: $1.3=\\dfrac{AD}{5}$, so $AD=6.5$. Note that 6.5 and 13/2 are examples of ways to enter a correct answer."}, {"id": "f389569d", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "What is the perimeter of an equilateral triangle with a height of $39\\sqrt{3}$?", "choices": {"A": "117", "B": "$117\\sqrt{3}$", "C": "234", "D": "$1{,}521\\sqrt{3}$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. In an equilateral triangle, the height splits it into two 30-60-90 triangles, where the height is the side opposite the $60°$ angle. If the height is $39\\sqrt{3}$, the side opposite the $30°$ angle is $39$, and the hypotenuse (side of the equilateral triangle) is $2(39)=78$. The perimeter is $3(78)=234$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "e3158182", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "Acute angle $P$ has a measure of $p$ radians, and acute angle $T$ has a measure of $t$ radians. The function $g$ is defined by $g(x)=p(8)^x+6t$. If $\\sin p=\\cos t$, which of the following represents the value of $g(0)$ in terms of $t$?", "choices": {"A": "$6t+\\pi$", "B": "$6t$", "C": "$5t+\\pi$", "D": "$5t+\\dfrac{\\pi}{2}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. Since $\\sin p=\\cos t$ for acute angles, $p+t=\\dfrac{\\pi}{2}$, so $p=\\dfrac{\\pi}{2}-t$. Substituting $x=0$ and $p=\\frac{\\pi}{2}-t$ into $g(x)=p(8)^x+6t$: $g(0)=\\left(\\frac{\\pi}{2}-t\\right)(8)^0+6t=\\left(\\frac{\\pi}{2}-t\\right)(1)+6t=\\frac{\\pi}{2}-t+6t=5t+\\frac{\\pi}{2}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "98e02472", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "In right triangle $XYZ$, angles $X$ and $Z$ are acute angles. Point $R$ lies on $\\overline{XZ}$ such that $\\overline{YR}$ is perpendicular to $\\overline{XZ}$. The measure of $\\angle XZY$ is $a°$, the measure of $\\angle XYR$ is $b°$, and the length of $\\overline{XY}$ is $19$. If $\\sin a°=\\dfrac{12}{13}$, what is the value of $\\tan b°$?", "choices": null, "table": null, "correctAnswer": ["2.4", "12/5"], "rationale": "The correct answer is $\\dfrac{12}{5}$. Since $\\angle Y$ is a right angle made up of $\\angle XYR$ and $\\angle ZYR$, and $YR\\perp XZ$ makes $\\angle XRY$ and $\\angle ZRY$ right angles, it can be shown that $a=b$ (both angles $XZY$ and $XYR$ are complementary to the same angle). So $\\sin b°=\\frac{12}{13}$ too. In right triangle $XRY$, if the opposite leg to $\\angle XYR$ is $12k$ and the hypotenuse is $13k$, the adjacent leg is $\\sqrt{(13k)^2-(12k)^2}=5k$. So $\\tan b°=\\dfrac{12k}{5k}=\\dfrac{12}{5}$. Note that 12/5 and 2.4 are examples of ways to enter a correct answer."}, {"id": "de9148c4", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Easy", "question": "Which equation shows the relationship between the side lengths of the triangle shown?\n\n[[FIGURE:de9148c4.png]]\n(Note: Figure not drawn to scale. Right triangle with the right angle at bottom-right; horizontal leg labeled $12$ at the bottom; vertical leg labeled $3$ on the right; hypotenuse labeled $c$ on the upper-left side.)", "choices": {"A": "$12\\cdot3=c$", "B": "$12+3=c$", "C": "$12^2+3^2=c^2$", "D": "$12^2-3^2=c^2$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. The Pythagorean theorem states $a^2+b^2=c^2$ for legs $a,b$ and hypotenuse $c$. Substituting $12$ and $3$ for the legs: $12^2+3^2=c^2$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "4fb972f2", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "In right triangle $QRS$, the length of hypotenuse $SQ$ is $4\\sqrt{82}$ and the length of side $QR$ is $4$. What is the length of side $RS$?", "choices": null, "table": null, "correctAnswer": ["36"], "rationale": "The correct answer is $36$. By the Pythagorean theorem: $4^2+RS^2=(4\\sqrt{82})^2$, so $16+RS^2=1{,}312$, giving $RS^2=1{,}296$. Taking the positive square root: $RS=36$."}, {"id": "6c67dd47", "domain": "Geometry and Trigonometry", "skill": "Right triangles and trigonometry", "difficulty": "Hard", "question": "In the figure shown, the measure of angle $X$ is $54°$. The length of $\\overline{XY}$ is $26$ units and the length of $\\overline{XZ}$ is $19$ units. What is the area, in square units, of triangle $XYZ$?\n\n[[FIGURE:6c67dd47.png]]\n(Note: Figure not drawn to scale. Triangle XYZ with X at bottom-left, Y at bottom-right (XY is the horizontal base), Z at top; an altitude is drawn from Z perpendicular to XY, meeting it at a right-angle mark.)", "choices": {"A": "247", "B": "494", "C": "$247\\sin54°$", "D": "$494\\sin54°$"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Area $=\\frac12 bh$ with base $XY=26$. The height $h$ from $Z$ satisfies $\\sin54°=\\frac{h}{19}$ (since $XZ=19$), so $h=19\\sin54°$. Area $=\\frac12(26)(19\\sin54°)=247\\sin54°$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "d12bca0a", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "The circle shown has its center at $(0,0)$. What is the value of $k$?\n\n[[FIGURE:d12bca0a.png]]\n(Note: Figure not drawn to scale. Circle centered at origin O; point $(8,0)$ lies on the circle on the positive x-axis; point $(2,k)$ lies on the circle in the upper-left region.)", "choices": {"A": "6", "B": "7", "C": "8", "D": "$\\sqrt{60}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The circle's equation is $x^2+y^2=r^2$. Since $(8,0)$ is on the circle, $r=8$, so $x^2+y^2=64$. Since $(2,k)$ is on the circle: $4+k^2=64$, so $k^2=60$, giving $k=\\sqrt{60}$ (positive since $(2,k)$ is above the x-axis).\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This is the $x$-coordinate of one of the circle's $x$-intercepts, not the value of $k$."}, {"id": "408b39ea", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Medium", "question": "\\[(x-3)^2+(y+16)^2=289\\]\nThe graph of the given equation is a circle in the $xy$-plane. The point $(q,s)$ lies on the circle. Which of the following is NOT a possible value of $q$?", "choices": {"A": "$-17$", "B": "$-3$", "C": "3", "D": "17"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. The circle has form $(x-h)^2+(y-k)^2=r^2$ with $r^2=289$, so $r=17$. The center is $(3,-16)$. So $x$-coordinates on the circle satisfy $3-17\\le q\\le 3+17$, i.e. $-14\\le q\\le20$. Since $-17$ doesn't satisfy this, it's NOT possible.\n\nChoice B is incorrect. $-3$ satisfies $-14\\le q\\le20$, so it is possible.\n\nChoice C is incorrect. $3$ satisfies $-14\\le q\\le20$, so it is possible.\n\nChoice D is incorrect. $17$ satisfies $-14\\le q\\le20$, so it is possible."}, {"id": "8493fd10", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "\\[x^2+x\\sqrt{t}+y^2-y-65=0\\]\nThe given equation, where $t$ is a constant, defines a circle in the $xy$-plane. The radius of this circle is $\\sqrt{83}$. What is the value of $t$?", "choices": {"A": "73", "B": "71", "C": "37", "D": "35"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Rewriting in center-radius form by completing the square: $\\left(x+\\dfrac{\\sqrt t}{2}\\right)^2+\\left(y-\\dfrac12\\right)^2=65+\\dfrac{t}{4}+\\dfrac14=\\dfrac{261}{4}+\\dfrac t4$. So $r^2=\\dfrac{261}{4}+\\dfrac t4$. Since $r=\\sqrt{83}$, $r^2=83$. So $\\dfrac{261}{4}+\\dfrac t4=83$; multiplying by $4$: $261+t=332$, so $t=71$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "267f82b5", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Medium", "question": "A circle in the $xy$-plane has the equation $(x-19)^2+(y-17)^2=64k^2$, where $k$ is a positive constant. Which of the following gives the center of the circle and its radius?", "choices": {"A": "The center is at $(19,17)$, and the radius is $8$.", "B": "The center is at $(19,17)$, and the radius is $8k$.", "C": "The center is at $(19,17)$, and the radius is $64$.", "D": "The center is at $(19,17)$, and the radius is $64k$."}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Comparing to $(x-h)^2+(y-k)^2=r^2$: center $(19,17)$, and $r^2=64k^2$, so $r=8k$ (positive root).\n\nChoice A is incorrect. This circle has equation $(x-19)^2+(y-17)^2=64$, not $=64k^2$.\n\nChoice C is incorrect. This circle has equation $(x-19)^2+(y-17)^2=4{,}096$, not $=64k^2$.\n\nChoice D is incorrect. This circle has equation $(x-19)^2+(y-17)^2=4{,}096k^2$, not $=64k^2$."}, {"id": "a5ff1a96", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "In the $xy$-plane, circle $M$ is the graph of the equation $(x-4)^2+(y-5)^2=9$. Circle $P$ has the same center as circle $M$ but has a radius that is twice the radius of circle $M$. Which equation represents circle $P$?", "choices": {"A": "$(x-4)^2+(y-5)^2=18$", "B": "$(x-4)^2+(y-5)^2=36$", "C": "$(x-8)^2+(y-10)^2=9$", "D": "$(x-8)^2+(y-10)^2=18$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Circle $M$ has center $(4,5)$ and radius $3$ (since $9=3^2$). Circle $P$ has the same center $(4,5)$ and radius $2(3)=6$, giving $(x-4)^2+(y-5)^2=6^2=36$.\n\nChoice A is incorrect. This has radius $\\sqrt2(3)$, not $2(3)$.\n\nChoice C is incorrect. This has center $(8,10)$, not $(4,5)$, and radius $3$, not $2(3)$.\n\nChoice D is incorrect. This has center $(8,10)$, not $(4,5)$, and radius $\\sqrt2(3)$, not $2(3)$."}, {"id": "186fdbca", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Easy", "question": "A circle has a diameter of $12.6$ centimeters. What is the radius of the circle, in centimeters?", "choices": null, "table": null, "correctAnswer": ["6.3", "63/10"], "rationale": "The correct answer is $6.3$. The diameter equals $2r$, so $12.6=2r$, giving $r=6.3$. Note that 6.3 and 63/10 are examples of ways to enter a correct answer."}, {"id": "149021da", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "A circle has center $P$, and points $A$ and $B$ lie on the circle. The measure of arc $AB$ is $45°$ and the length of arc $AB$ is $4\\pi$ units. What is the length, in units, of the radius of the circle?", "choices": null, "table": null, "correctAnswer": ["16"], "rationale": "The correct answer is $16$. The ratio of arc measure to $360°$ equals the ratio of arc length to circumference: $\\dfrac{45}{360}=\\dfrac{4\\pi}{2\\pi r}$, i.e. $\\dfrac18=\\dfrac2r$. Multiplying both sides by $8r$: $r=16$."}, {"id": "11301fb6", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Medium", "question": "The difference between the measure of angle $A$ and the measure of angle $B$ is $-\\dfrac56\\pi$ radians. Which expression shows the difference between the measure of angle $A$ and the measure of angle $B$, in degrees?", "choices": {"A": "$-\\dfrac56\\pi\\cdot\\dfrac{360°}{\\pi}$", "B": "$-\\dfrac56\\pi\\cdot\\dfrac{180°}{\\pi}$", "C": "$-\\dfrac56\\pi\\cdot\\dfrac{\\pi}{180°}$", "D": "$-\\dfrac56\\cdot\\dfrac{180°}{\\pi}$"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Since $\\pi$ radians $=180°$, converting radians to degrees means multiplying by $\\dfrac{180°}{\\pi}$. So the difference in degrees is $-\\dfrac56\\pi\\cdot\\dfrac{180°}{\\pi}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "10e059a6", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "The measure of angle $A$ is $\\dfrac{\\pi}{216}$ radians. The measure of angle $B$ is $36$ times the measure of angle $A$. What is the value of $\\cos B$?", "choices": {"A": "0", "B": "$\\dfrac12$", "C": "$\\dfrac{\\sqrt2}{2}$", "D": "$\\dfrac{\\sqrt3}{2}$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The measure of angle $B$ is $36\\left(\\dfrac{\\pi}{216}\\right)=\\dfrac{\\pi}{6}$ radians. On the unit circle, traveling $\\dfrac{\\pi}{6}$ counterclockwise from $(1,0)$ gives the point $\\left(\\dfrac{\\sqrt3}{2},\\dfrac12\\right)$, so $\\cos B=\\dfrac{\\sqrt3}{2}$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect. This is the value of $\\sin B$, not $\\cos B$.\n\nChoice C is incorrect and may result from conceptual or calculation errors."}, {"id": "9f9112ab", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "The measure of angle $L$ is $60$ degrees. If the measure of angle $L$ is $\\dfrac{\\pi}{n}$ radians, where $n$ is a constant, what is the value of $n$?", "choices": null, "table": null, "correctAnswer": ["3"], "rationale": "The correct answer is $3$. Converting to radians: $60\\times\\dfrac{\\pi}{180}=\\dfrac{\\pi}{3}$. Since this equals $\\dfrac{\\pi}{n}$, $\\dfrac1n=\\dfrac13$, so $n=3$."}, {"id": "27f1db42", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "In the $xy$-plane, circle $F$ is defined by the equation $(x+8)^2+(y+8)^2=25$. Circle $G$ has the same center as circle $F$, and the radius of circle $G$ is $2$ units greater than the radius of circle $F$. Circle $G$ is defined by the equation $(x+8)^2+(y+8)^2=p$, where $p$ is a constant. What is the value of $p$?", "choices": null, "table": null, "correctAnswer": ["49"], "rationale": "The correct answer is $49$. Circle $F$: center $(-8,-8)$, radius $5$ (since $25=5^2$). Circle $G$ has the same center and radius $5+2=7$, so $p=7^2=49$."}, {"id": "44d67c6c", "domain": "Geometry and Trigonometry", "skill": "Circles", "difficulty": "Hard", "question": "\\[x^2+y^2-10x-8y-14n=0\\]\nThe given equation represents circle A in the $xy$-plane, where $n$ is a constant. Point $(11,8)$ lies on circle B, which has the same center but twice the diameter as circle A. What is the value of $n$?", "choices": null, "table": null, "correctAnswer": ["-2"], "rationale": "The correct answer is $-2$. Completing the square: $(x-5)^2+(y-4)^2=14n+41$. Circle A has center $(5,4)$ and radius $\\sqrt{14n+41}$. Circle B has the same center and twice the radius: $2\\sqrt{14n+41}$, giving equation $(x-5)^2+(y-4)^2=4(14n+41)$. Substituting $(11,8)$: $(11-5)^2+(8-4)^2=4(14n+41)$, so $36+16=4(14n+41)$, i.e. $52=4(14n+41)$, giving $13=14n+41$. So $14n=-28$, and $n=-2$."}, {"id": "1fe41c6b", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "The table gives the areas and perimeters of two similar rectangles, where $n$ is a constant.\n\n[[TABLE]]\n\nWhat is the value of $n$?", "choices": {"A": "2,100", "B": "1,680", "C": "840", "D": "420"}, "table": {"headers": ["", "Area (square inches)", "Perimeter (inches)"], "rows": [["Rectangle A", "630", "210"], ["Rectangle B", "2,520", "n"]]}, "correctAnswer": ["D"], "rationale": "Choice D is correct. For similar rectangles with scale factor $k$, area scales by $k^2$ and perimeter scales by $k$. Since $2{,}520=630k^2$, $k^2=4$, so $k=2$. So perimeter of B is $2(210)=420$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This results from using the area scale factor instead of the side-length scale factor."}, {"id": "124bc42b", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Easy", "question": "Rectangle $ABCD$ shown has a length of $7$ units and a width of $2$ units. What is the area, in square units, of rectangle $ABCD$?\n\n[[FIGURE:124bc42b.png]]\n(Note: Rectangle plotted in the xy-plane with vertices B(2,9), C(4,9), A(2,2), D(4,2).)", "choices": {"A": "5", "B": "9", "C": "14", "D": "28"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Area $=\\ell w=(7)(2)=14$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "30aa51b7", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "A rectangle is formed by the four points shown. What is the area, in square units, of the rectangle?\n\n[[FIGURE:30aa51b7.png]]\n(Note: Points plotted in the xy-plane: $(-4,-1)$, $(4,5)$, $(7,1)$, $(-1,-5)$, forming a rectangle.)", "choices": null, "table": null, "correctAnswer": ["50"], "rationale": "The correct answer is $50$. The area of a rectangle is $\\ell w$. The side from $(-4,-1)$ to $(4,5)$ has length $\\sqrt{(4-(-4))^2+(5-(-1))^2}=\\sqrt{100}=10$. The adjacent side from $(4,5)$ to $(7,1)$ has length $\\sqrt{(7-4)^2+(1-5)^2}=\\sqrt{25}=5$. So the area is $(10)(5)=50$."}, {"id": "179edb12", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "A right circular cone has a height of $22$ centimeters (cm) and a base with a diameter of $18$ cm. The volume of this cone is $n\\pi\\ \\text{cm}^3$. What is the value of $n$?", "choices": null, "table": null, "correctAnswer": ["594"], "rationale": "The correct answer is $594$. The radius is $18/2=9$ cm. Volume $V=\\frac13\\pi r^2h=\\frac13\\pi(9)^2(22)=594\\pi$. So $n=594$."}, {"id": "c8ab85ad", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Easy", "question": "Which expression represents the area, in square inches, of a square with a side length of $35$ inches?", "choices": {"A": "$\\sqrt{35}$", "B": "$35+35$", "C": "$(4)(35)$", "D": "$35^2$"}, "table": null, "correctAnswer": ["D"], "rationale": "Choice D is correct. The area of a square is $s^2$, where $s$ is the side length. Substituting $35$ for $s$ gives $35^2$.\n\nChoice A is incorrect and may result from conceptual errors.\n\nChoice B is incorrect and may result from conceptual errors.\n\nChoice C is incorrect. This expression represents the perimeter, not the area, of the square."}, {"id": "e6c557f9", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "The edge length, in inches, of cube Y is $\\dfrac{3}{88}$ the edge length, in inches, of cube X. The surface area, in square inches, of cube Y is $n$ times the surface area, in square inches, of cube X. What is the value of $n$?", "choices": {"A": "$\\dfrac{9}{7{,}744}$", "B": "$\\dfrac{27}{3{,}872}$", "C": "$\\dfrac{3}{88}$", "D": "$\\dfrac{9}{44}$"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. For similar figures with a length scale factor of $k$, area scales by $k^2$. Since the edge length scale factor is $\\frac{3}{88}$, the surface area scale factor is $\\left(\\frac{3}{88}\\right)^2=\\frac{9}{7{,}744}$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "f3f06c3a", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Easy", "question": "In the rectangle shown, $x=7$ centimeters and $y=5$ centimeters. What is the area, in square centimeters, of the rectangle?\n\n(Note: Figure not drawn to scale. A rectangle labeled with $x$ along the top side and $y$ along the right side.)", "choices": {"A": "7", "B": "12", "C": "35", "D": "40"}, "table": null, "correctAnswer": ["C"], "rationale": "Choice C is correct. Area $=\\ell w$, where $\\ell$ is the length and $w$ is the width. Here $x$ is the length and $y$ is the width: $A=(7)(5)=35$.\n\nChoice A is incorrect. This is the length, not the area, of the rectangle.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "73e1b793", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "Right rectangular prism P is similar to right rectangular prism Q. The volume of prism P is $972$ cubic centimeters ($\\text{cm}^3$), and the volume of prism Q is $36\\ \\text{cm}^3$. One edge of prism P has a length of $12$ cm. What is the length, in cm, of the corresponding edge of prism Q?", "choices": null, "table": null, "correctAnswer": ["4"], "rationale": "The correct answer is $4$. For similar prisms with edge scale factor $k$, volume scales by $k^3$. $972=36k^3$, so $k^3=27$, giving $k=3$. Since prism P's edge is $3$ times prism Q's corresponding edge, prism Q's edge is $12/3=4$."}, {"id": "cab8f907", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Easy", "question": "The figure shows the lengths, in units, of two sides of a triangle. What is the area, in square units, of the triangle?\n\n[[FIGURE:cab8f907.png]]\n(Note: Figure not drawn to scale. Right triangle with the right angle at bottom-right; horizontal base labeled $9$; vertical leg on the right labeled $4$; hypotenuse is the slanted left side.)", "choices": {"A": "18", "B": "13", "C": "9", "D": "4"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Area $=\\frac12 bh=\\frac12(9)(4)=18$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This is the length of the base, not the area.\n\nChoice D is incorrect. This is the height, not the area."}, {"id": "9fdc4eaa", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "A right square pyramid has a total surface area of $70{,}560$ square inches, and the combined surface area of the four lateral faces of this pyramid is $38{,}160$ square inches. What is the height, in inches, of this pyramid?", "choices": {"A": "56", "B": "90", "C": "106", "D": "180"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Total surface area = base area + lateral area, so base area $=70{,}560-38{,}160=32{,}400=s^2$, giving $s=180$ (side length of square base). Each lateral face has area $\\dfrac{38{,}160}{4}=9{,}540$. The area of a lateral face is $A=\\frac12 s\\ell$, where $\\ell$ is the slant height: $9{,}540=\\frac12(180)\\ell=90\\ell$, so $\\ell=106$. In the right square pyramid, a right triangle relates height $h$, half the base side $\\frac12 s$, and slant height $\\ell$: $h^2+\\left(\\frac12 s\\right)^2=\\ell^2$. Substituting $s=180,\\ell=106$: $h^2+90^2=106^2$, so $h^2+8{,}100=11{,}236$, giving $h^2=3{,}136$, so $h=56$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect. This is the pyramid's slant height, not its height.\n\nChoice D is incorrect. This is the side length of the pyramid's base, not its height."}, {"id": "f6ca90cc", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "A right prism has a square base with side lengths of $10$ inches. The height of the prism is $58$ inches. What is the volume, in cubic inches, of the prism?", "choices": null, "table": null, "correctAnswer": ["5800"], "rationale": "The correct answer is $5{,}800$. Volume of a right prism with square base: $V=s^2h=(10)^2(58)=5{,}800$."}, {"id": "25cc5327", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Medium", "question": "The base of a right rectangular pyramid has a length of $27$ centimeters and a width of $2$ centimeters. The height of this pyramid is $7$ centimeters. What is the volume, in cubic centimeters, of this pyramid?", "choices": null, "table": null, "correctAnswer": ["126"], "rationale": "The correct answer is $126$. Volume of a right rectangular pyramid: $V=\\frac13\\ell wh=\\frac13(27)(2)(7)=126$."}, {"id": "4757123b", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Hard", "question": "Trapezoid A and trapezoid B are similar. The length of each side of trapezoid A is $41$ times the length of the corresponding side of trapezoid B. The area of trapezoid A is how many times as large as the area of trapezoid B?", "choices": null, "table": null, "correctAnswer": ["1681"], "rationale": "The correct answer is $1{,}681$. For similar figures with side-length scale factor $k$, area scales by $k^2$. Here $k=41$, so the area scale factor is $41^2=1{,}681$."}, {"id": "17049054", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Easy", "question": "The length of a side of square X is $9$ centimeters. The area of rectangle Y is $32$ square centimeters. What is the total area, in square centimeters, of square X and rectangle Y?", "choices": {"A": "145", "B": "113", "C": "82", "D": "81"}, "table": null, "correctAnswer": ["B"], "rationale": "Choice B is correct. Area of square X $=9^2=81$. Total area $=81+32=113$.\n\nChoice A is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect. This is the area of square X alone, not the total area."}, {"id": "42155bac", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Medium", "question": "The area of one of the bases of a right circular cylinder is $81$ square centimeters, and the volume of the cylinder is $2{,}187$ cubic centimeters. What is the height, in centimeters, of the cylinder?", "choices": {"A": "27", "B": "2,025", "C": "2,106", "D": "177,147"}, "table": null, "correctAnswer": ["A"], "rationale": "Choice A is correct. Volume $V=\\pi r^2h$, where $\\pi r^2$ is the base area. So $2{,}187=81h$, giving $h=27$.\n\nChoice B is incorrect and may result from conceptual or calculation errors.\n\nChoice C is incorrect and may result from conceptual or calculation errors.\n\nChoice D is incorrect and may result from conceptual or calculation errors."}, {"id": "1b687ae3", "domain": "Geometry and Trigonometry", "skill": "Area and volume", "difficulty": "Medium", "question": "The area of a triangle is $36$ square units. If the height of this triangle is $2$ units, what is the length, in units, of the base of this triangle?", "choices": null, "table": null, "correctAnswer": ["36"], "rationale": "The correct answer is $36$. Area $A=\\frac12 bh$. Substituting $A=36,h=2$: $36=\\frac12 b(2)=b$, so $b=36$."}];
